/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A14 checkpoint 1/4: characterize–chemosynthesis (20 frozen headwords). */
'use strict';
const D=globalThis.RA.D;
const q=(w,n,s,p,options,answer,explain)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options,answer,explain});
const m=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const c=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const e=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${encodeURIComponent(w.toLowerCase())}`});
D('characterize',{etymology:e('characterize 由 character 加动词后缀 -ize 构成；character 经古法语来自拉丁语 character，原指刻印或标记，后发展为描述特点、以某特点为标志。','characterize'),contexts:[c('characterize.s2','城市规划','Low-rise brick buildings characterize the old quarter, where narrow lanes and small courtyards have survived for generations.','低层砖房是老城区的典型特征，狭窄小巷和小庭院已保存数代。','Low-rise brick buildings characterize the old quarter / where narrow lanes and small courtyards have survived for generations.','characterize 在此作及物动词，主语“砖房”是该地区的典型特征。','主语作为典型特点标志地点，体现 characterize.s2。')],mistakes:[m('The novel is characterized its heroine as patient and observant.','The novel characterizes its heroine as patient and observant.','主动句中 characterize 直接带宾语；characterized its heroine 缺少 be 才能构成被动。')],quiz:[q('characterize',1,1,'To characterize a person is to?',['describe that person’s distinguishing qualities','charge the person a fee','measure the person’s height only'],'describe that person’s distinguishing qualities','characterize.s1 指描述人或事物的特征。'),q('characterize',2,2,'“Quiet streets characterize the village” means quiet streets?',['are a typical feature of the village','were built by every villager','are being measured in the village'],'are a typical feature of the village','characterize.s2 表示某事物以另一事物为典型特点。'),q('characterize',3,1,'A review characterizes the film as bleak. What does it do?',['describes the film’s qualities','sets the film’s ticket price','casts the film’s actors'],'describes the film’s qualities','as bleak 是对影片特点的描述。'),q('characterize',4,2,'Which statement uses characterize to identify a typical feature?',['Frequent fog characterizes the coast.','The guide characterized the map yesterday.','The actors characterized the script.'],'Frequent fog characterizes the coast.','雾是海岸典型特点，使用其“以…为特征”义。')]});
D('charcoal',{etymology:e('charcoal 源自中古英语与古法语 charcol；前部关联古法语 charbon“木炭”，后部与 cole“煤”相关，指木材隔绝空气烧制成的炭。','charcoal'),contexts:[c('charcoal.s2','美术课堂','She shaded the portrait in charcoal, using the side of the stick for broad shadows and its point for fine lines.','她用炭笔为肖像画上明暗，先用笔侧涂大片阴影，再用笔尖描细线。','She shaded the portrait in charcoal / using the side of the stick for broad shadows / and its point for fine lines.','in charcoal 表示使用木炭媒材；分词短语说明画法。','炭笔及绘画技法直接体现绘画媒材义 s2。')],mistakes:[m('The blacksmith burned charcoal in the forge because it was a pale liquid fuel with no carbon.','The blacksmith burned charcoal in the forge because it was a black carbon-rich solid fuel.','木炭是含碳的黑色固体，不是浅色液体。')],quiz:[q('charcoal',1,1,'Charcoal used as fuel is usually made by?',['heating wood with little oxygen','freezing seawater','grinding fresh leaves'],'heating wood with little oxygen','charcoal.s1 是木材慢烧制成的黑色燃料。'),q('charcoal',2,2,'An artist drawing in charcoal uses?',['a black drawing stick or its marks','a small lump of table salt','a sheet of colored glass'],'a black drawing stick or its marks','charcoal.s2 指炭笔及其画作。'),q('charcoal',3,1,'Which object could be charcoal fuel?',['a black carbon-rich lump for a brazier','a clear liquid in a glass','a coil of copper wire'],'a black carbon-rich lump for a brazier','木炭可作火盆燃料。'),q('charcoal',4,2,'A portrait “in charcoal” was made with?',['charcoal drawing material','watercolor only','a camera lens'],'charcoal drawing material','in charcoal 表示以炭笔绘制。')]});
D('charge',{etymology:e('charge 经古法语 charger“装载、使负担”进入英语，最终源自拉丁语 carricare“装车”；由装载发展出收费、给电池充能、控告及责任等义。','charge'),contexts:[c('charge.s2','设备维护','Before the field trip, Maya charged the radio overnight and checked that its battery indicator showed a full bar.','野外考察前，玛雅给无线电充了一夜电，并检查电量指示是否满格。','Before the field trip / Maya charged the radio overnight / and checked that its battery indicator showed a full bar.','charge 是及物动词，radio 是被充电设备。','电池电量充满说明是向设备供电的 charge.s2。')],mistakes:[m('The hotel charged us nothing for the room, then collected an additional $90 as the room fee.','The hotel charged us $90 for the room, then collected that amount as the room fee.','若另收90美元房费，就不能说没有收费；charge表示要价或收取费用。')],quiz:[q('charge',1,1,'If a shop charges £8 for a book, it?',['asks the buyer to pay £8','supplies electricity to the book','accuses the book of a crime'],'asks the buyer to pay £8','charge.s1 是向某人收取一定金额。'),q('charge',2,2,'To charge a depleted phone is to?',['supply electrical energy to it','formally accuse its owner','set its sale price'],'supply electrical energy to it','charge.s2 指给设备或电池充电。'),q('charge',3,3,'Police charge a suspect when they?',['formally accuse the suspect of an offense','ask the suspect to recharge a battery','put the suspect in charge of a shop'],'formally accuse the suspect of an offense','法律语境中的 charge.s3 是正式指控。'),q('charge',4,4,'“She is in charge of the archive” means she?',['is responsible for managing it','must pay the archive’s entry fee','has accused the archive of theft'],'is responsible for managing it','in charge of 表示负责管理。')]});
D('chariot',{etymology:e('chariot 经法语 charriot 进入英语，来自 char“车”及 diminutive 后缀；其更早来源与拉丁语 carrus“车辆”有关，常指古代马拉双轮车。','chariot'),contexts:[c('chariot.s1','古代史','The museum relief shows a driver standing in a two-wheeled chariot as a pair of horses pulls it across the battlefield.','博物馆浮雕描绘一名车手站在双轮战车上，由两匹马拉着穿过战场。','The museum relief shows a driver standing in a two-wheeled chariot / as a pair of horses pulls it across the battlefield.','chariot 是介词 in 的宾语；as 从句交代马拉车的情形。','双轮、马拉并用于战场，符合古代战车义。')],mistakes:[m('The ancient chariot had four engines and traveled underwater without horses or wheels.','The ancient chariot had two wheels and was pulled by horses.','古代 chariot 是马拉双轮车，不是现代发动机驱动的潜水艇。')],quiz:[q('chariot',1,1,'An ancient chariot was typically?',['a light horse-drawn two-wheeled vehicle','a steam-powered ship','a stone building for grain'],'a light horse-drawn two-wheeled vehicle','chariot.s1 指古代马拉双轮车。'),q('chariot',2,1,'A chariot race would most likely take place?',['with horses pulling small carts','between underwater submarines','using stationary farm tools'],'with horses pulling small carts','战车比赛由马拉车辆竞速。'),q('chariot',3,1,'Which detail identifies a chariot?',['two wheels and a horse team','a propeller and deep hull','a fixed roof and no wheels'],'two wheels and a horse team','双轮并由马拉是其关键特征。'),q('chariot',4,1,'In an ancient battle, a chariot served as?',['a mobile horse-drawn vehicle','a hand-held musical instrument','a type of armor worn on the foot'],'a mobile horse-drawn vehicle','古代战场上战车是机动马拉车辆。')]});
D('charisma',{etymology:e('charisma 经教会拉丁语与希腊语 charisma“恩赐、神恩”进入英语，源自 charizesthai“施恩”；现代常指吸引并影响他人的个人魅力。','charisma'),contexts:[c('charisma.s1','政治传播','The candidate’s charisma drew a large crowd, but voters still asked for specific plans on housing and public transport.','候选人的个人魅力吸引了大批人群，但选民仍要求他提出住房和公共交通的具体计划。','The candidate’s charisma drew a large crowd / but voters still asked for specific plans / on housing and public transport.','charisma 是所有格结构的主语；but 表示魅力与政策审查并存。','能吸引大批听众体现领袖个人魅力 s1。')],mistakes:[m('The leader lacked charisma, so audiences were irresistibly drawn to her and eagerly followed every proposal.','The leader had charisma, so audiences were drawn to her and followed her proposals.','吸引并影响追随者的特质正是 charisma；原句前后矛盾。')],quiz:[q('charisma',1,1,'A leader with charisma can often?',['attract and influence followers','repair a battery by charging it','describe a person’s height only'],'attract and influence followers','charisma.s1 指吸引并影响他人的个人魅力。'),q('charisma',2,2,'In a theological text, charisma may mean?',['a gift believed to come from God','a tax payment fixed by law','a kind of ancient horse cart'],'a gift believed to come from God','charisma.s2 是神学中的神授恩赐。'),q('charisma',3,1,'A speaker’s charisma is best shown by?',['listeners feeling drawn to the speaker','a microphone being switched off','an audience reading silently at home'],'listeners feeling drawn to the speaker','魅力能吸引听众。'),q('charisma',4,2,'A religious writer calls healing a charisma. The word refers to?',['a special divine gift','a stage costume','a method of measuring sound'],'a special divine gift','宗教语境里 charisma 可指神所赐的特殊能力。')]});
D('charismatic',{etymology:e('charismatic 由 charisma 加形容词后缀 -atic 构成；charisma 经希腊语 charisma“恩赐”进入英语，现代形容凭个人魅力吸引并影响他人的人。','charismatic'),contexts:[c('charismatic.s1','公共演讲','A charismatic guide kept the children engaged by telling lively stories about the fossils instead of reciting dates from a chart.','一位有魅力的导游用生动故事讲解化石，让孩子们兴致盎然，而不是照图表念日期。','A charismatic guide kept the children engaged / by telling lively stories about the fossils / instead of reciting dates from a chart.','charismatic 修饰 guide；by telling 表示吸引孩子的方式。','导游凭表达吸引听众，体现该词义。')],mistakes:[m('The charismatic speaker failed to hold anyone’s attention, and the audience left before the first sentence ended.','The dull speaker failed to hold anyone’s attention, and the audience left before the first sentence ended.','charismatic 表示有吸引力、能影响他人；无人愿听与其义不合。')],quiz:[q('charismatic',1,1,'A charismatic performer is likely to?',['attract people through personal charm','make everyone feel bored immediately','work only with chemical substances'],'attract people through personal charm','charismatic.s1 指凭个人魅力吸引他人。'),q('charismatic',2,1,'Which description best fits a charismatic leader?',['people are drawn to the leader’s presence','the leader avoids every conversation','the leader is a battery charger'],'people are drawn to the leader’s presence','有魅力的领导者能吸引并影响他人。'),q('charismatic',3,1,'A charismatic teacher might keep a class engaged by?',['speaking in a compelling, engaging way','reading every line in a flat monotone','turning off all the lights and leaving'],'speaking in a compelling, engaging way','引人入胜的表达体现 charismatic。'),q('charismatic',4,1,'Charismatic describes a person’s ability to?',['attract and influence others','ask a fixed fee','change a word into its plural'],'attract and influence others','该形容词指以个人魅力吸引、影响他人。')]});
D('chary',{etymology:e('chary 源自古英语 cearig“忧虑、谨慎”，与 care“关心、顾虑”同源；现代常见 be chary of，表示因顾虑风险而谨慎，也可指不轻易给予。','chary'),contexts:[c('chary.s1','投资决策','After losing money in a speculative fund, Mei was chary of investing in products she did not understand.','在一只投机基金上亏钱后，梅对投资自己不了解的产品格外谨慎。','After losing money in a speculative fund / Mei was chary of investing in products / she did not understand.','be chary of 后接名词或动名词，表达戒备或谨慎。','因以往损失而避开风险，符合 chary.s1。')],mistakes:[m('He was chary of the guaranteed risk-free offer and signed immediately without reading a word.','He was wary of the supposedly risk-free offer and read the terms before deciding.','chary 表示小心戒备；毫不审阅便立即签字与谨慎义冲突。')],quiz:[q('chary',1,1,'If a buyer is chary of a deal, the buyer is?',['cautious about possible risks','eager to accept without checking','responsible for charging a fee'],'cautious about possible risks','chary.s1 指因可能的风险而谨慎。'),q('chary',2,2,'Someone chary with praise is?',['slow to give praise freely','always lavish with compliments','unable to hear compliments'],'slow to give praise freely','chary.s2 表示不轻易给出赞美等东西。'),q('chary',3,1,'Which sentence uses chary in its cautious sense?',['She was chary of signing an unfamiliar contract.','She was chary with the medals she awarded.','The chary battery was fully charged.'],'She was chary of signing an unfamiliar contract.','对陌生合同谨慎，体现 s1。'),q('chary',4,2,'A manager chary of praise gives it?',['sparingly, only when deserved','to everyone every minute','only as a form of punishment'],'sparingly, only when deserved','对赞美吝惜，符合 s2。')]});
D('chaste',{etymology:e('chaste 经古法语来自拉丁语 castus“纯洁、贞洁”，与 castigate 的拉丁词根相关；除贞洁外也形容风格简洁、克制、不加繁饰。','chaste'),contexts:[c('chaste.s2','室内设计','The architect chose a chaste interior of pale stone, clean lines, and almost no ornament, allowing daylight to define the rooms.','建筑师选择了素雅的室内风格：浅色石材、简洁线条，几乎没有装饰，让自然光勾勒房间。','The architect chose a chaste interior / of pale stone, clean lines, and almost no ornament / allowing daylight to define the rooms.','chaste 作定语修饰 interior；冒号后列出素雅风格的具体表现。','少装饰、线条简洁体现 chaste.s2。')],mistakes:[m('The gallery described the chaste design as overloaded with gold leaf, carved angels, and decorative patterns on every surface.','The gallery described the ornate design as overloaded with gold leaf, carved angels, and decorative patterns on every surface.','遍布装饰与 chaste 的简朴素雅义相反。')],quiz:[q('chaste',1,1,'A person described as chaste traditionally?',['avoids sexual relations outside marriage','adds decoration to every surface','collects taxes for a town'],'avoids sexual relations outside marriage','chaste.s1 指贞洁、守身。'),q('chaste',2,2,'A chaste design is usually?',['simple and restrained','covered in unnecessary ornament','brightly chaotic and cluttered'],'simple and restrained','chaste.s2 形容简朴素雅、不事繁饰。'),q('chaste',3,2,'Which room has a chaste style?',['one with plain walls and clean lines','one with every wall covered in gilding','one filled from floor to ceiling with clutter'],'one with plain walls and clean lines','克制的装饰和线条表现简洁素雅。'),q('chaste',4,1,'In its moral sense, chaste is closest to?',['sexually pure or abstinent','carelessly extravagant','chemically reactive'],'sexually pure or abstinent','其传统道德义与贞洁相关。')]});
D('chateau',{etymology:e('chateau 来自法语 château，源自拉丁语 castellum“城堡、小堡垒”（castrum“小军营”的指小形式）；英语常指法国城堡或乡间大宅。','chateau'),contexts:[c('chateau.s1','法国旅行','The visitors toured a Loire Valley chateau, walking through its stone courtyard before viewing the restored rooms and gardens.','游客参观了卢瓦尔河谷的一座法国城堡，先穿过石砌庭院，再看修复后的房间和花园。','The visitors toured a Loire Valley chateau / walking through its stone courtyard / before viewing the restored rooms and gardens.','chateau 是 toured 的宾语；地点修饰说明在法国卢瓦尔河谷。','法国地区的大宅与城堡符合 chateau.s1。')],mistakes:[m('Their modest one-room garden shed was called a chateau although it had no large house or castle features.','Their grand French country house was called a chateau because of its scale and historic architecture.','chateau 指大型法国乡间住宅或城堡，不是简陋的小棚屋。')],quiz:[q('chateau',1,1,'A French chateau is usually?',['a large country house or castle','a small paper ticket','a kind of fishing net'],'a large country house or castle','chateau.s1 指大型法国乡间住宅或城堡。'),q('chateau',2,1,'A traveler in the Loire Valley might visit a?',['historic chateau','submarine dock','modern checkout counter'],'historic chateau','卢瓦尔河谷以法国城堡与大宅著称。'),q('chateau',3,1,'Which building best fits chateau?',['a grand historic French estate','a portable tent for one person','a narrow roadside mailbox'],'a grand historic French estate','规模宏大的法国乡间大宅符合词义。'),q('chateau',4,1,'The word chateau is of what language origin?',['French','Japanese','Swahili'],'French','chateau 是法语借词。')]});
D('cheapen',{etymology:e('cheapen 由 cheap 加动词后缀 -en 构成；cheap 经中古英语与古英语 cēap“交易、买卖”发展而来，动词既可使价格降低，也可使价值或体面受损。','cheapen'),contexts:[c('cheapen.s2','品牌管理','The company refused to flood the market with imitation goods, fearing that poor copies would cheapen the brand’s reputation.','公司拒绝让仿制品充斥市场，担心劣质复制品会贬损品牌声誉。','The company refused to flood the market with imitation goods / fearing that poor copies would cheapen the brand’s reputation.','cheapen 是 would 后的动词，品牌声誉是其宾语。','劣质复制品使声誉显得不值钱，体现贬损义 s2。')],mistakes:[m('Adding the gold trim cheapened the ring, raising its resale value and making it seem more prestigious.','Adding the gold trim enhanced the ring, raising its resale value and making it seem more prestigious.','提高售价、声望是提升而非贬低价值；cheapen 的含义相反。')],quiz:[q('cheapen',1,1,'A store may cheapen a product by?',['reducing its price','charging twice as much','making it impossible to buy'],'reducing its price','cheapen.s1 可指降低价格或市场价值。'),q('cheapen',2,2,'A tasteless joke can cheapen a serious ceremony by?',['making it seem less worthy or dignified','lowering the ceremony’s ticket price','increasing the number of guests'],'making it seem less worthy or dignified','cheapen.s2 指使某事显得不体面、不值钱。'),q('cheapen',3,1,'Which change would cheapen a product’s market value?',['a steep price reduction','a rise in demand and price','a new safety certification'],'a steep price reduction','大幅降价会降低商品市场价值。'),q('cheapen',4,2,'A careless slogan could cheapen a respected name, meaning it could?',['damage the name’s dignity or worth','raise the name’s market share automatically','translate the name into French'],'damage the name’s dignity or worth','这里 cheapen 是贬损声望。')]});
D('cheaply',{etymology:e('cheaply 由形容词 cheap 加副词后缀 -ly 构成，表示价格低，也可形容因质量或手段差而显得廉价、粗劣。','cheaply'),contexts:[c('cheaply.s1','家庭采购','The school bought the folding chairs cheaply in bulk, but inspected every hinge before using them in the auditorium.','学校以批量采购的方式低价买下折叠椅，但在礼堂使用前检查了每个铰链。','The school bought the folding chairs cheaply in bulk / but inspected every hinge / before using them in the auditorium.','cheaply 修饰 bought，说明采购价格低；but 引出质量检查。','低价批量购买体现 chiefly 的价格副词义。')],mistakes:[m('The museum cheaply restored the fragile painting with expert materials and painstaking care, making the work more valuable.','The museum carefully restored the fragile painting with expert materials and painstaking care, making the work more valuable.','专业精心的修复不应称作“粗劣地”；cheaply 的低质量用法带贬义。')],quiz:[q('cheaply',1,1,'If an item is bought cheaply, it is bought?',['for little money','at a very high price','without being purchased'],'for little money','cheaply.s1 表示花费少、价格便宜。'),q('cheaply',2,1,'“The shelf was cheaply made” may imply that it was?',['made with poor quality','crafted with exceptional care','sold only at a charity auction'],'made with poor quality','cheaply 也可指粗制滥造、质量低劣。'),q('cheaply',3,1,'Which sentence uses cheaply to mean at low cost?',['They found the tickets cheaply online.','The carpenter cheaply joined the pieces badly.','The room was cheapened by its paint.'],'They found the tickets cheaply online.','找到低价票体现价格低的副词义。'),q('cheaply',4,1,'A cheaply constructed bridge would raise concern about?',['poor workmanship or materials','its unusually high ticket price','the bridge’s role in a theater play'],'poor workmanship or materials','cheaply constructed 常暗示施工质量差。')]});
D('cheater',{etymology:e('cheater 由 cheat 加表示人的后缀 -er 构成；cheat 经古法语 escheat“没收的财产”进入英语，词义后来发展为欺骗、作弊者。','cheater'),contexts:[c('cheater.s1','考试纪律','The proctor removed the cheater from the exam after finding answers written on the inside of the student’s sleeve.','监考员发现学生袖子内侧写着答案后，将这名作弊者请出了考场。','The proctor removed the cheater from the exam / after finding answers written on the inside of the student’s sleeve.','cheater 是 removed 的宾语；after 引出发现作弊证据的时间。','暗藏答案欺骗考试规则，说明 cheater.s1。')],mistakes:[m('The honest chess player was called a cheater because she followed every rule and reported her own accidental mistake.','The dishonest chess player was called a cheater because he secretly moved an extra piece.','严格守规并主动报告失误不是作弊；cheater 指弄虚作假的人。')],quiz:[q('cheater',1,1,'A cheater in an exam is someone who?',['uses dishonest help to gain an unfair advantage','answers every question independently','checks the exam room’s temperature'],'uses dishonest help to gain an unfair advantage','cheater.s1 指作弊或欺诈的人。'),q('cheater',2,1,'Which person is clearly a cheater in a game?',['a player who secretly changes the score','a player who accepts the official result','a referee who explains a rule'],'a player who secretly changes the score','偷偷改分是故意作弊。'),q('cheater',3,1,'A cheater in a relationship has typically?',['broken a partner’s trust through infidelity','paid for dinner before it arrived','shared a calendar honestly'],'broken a partner’s trust through infidelity','cheater 也可指在亲密关系中不忠的人。'),q('cheater',4,1,'The ending -er in cheater marks?',['a person who performs the action','a past event only','a type of electrical charge'],'a person who performs the action','-er 可构成表示实施动作的人的名词。')]});
D('check-out',{etymology:e('check-out 是 check out 的名词化写法，由 check“核对、结账”与 out“离开”组成；在商店指付款离店，在酒店指办理离店手续，也可指收银处。','check-out'),contexts:[c('check-out.s1','酒店前台','At check-out, the receptionist reviewed the minibar charges, returned the room key, and printed the guests’ final bill.','办理退房时，前台核对了迷你吧费用、收回房卡，并打印了客人的最终账单。','At check-out / the receptionist reviewed the minibar charges / returned the room key / and printed the guests’ final bill.','check-out 作时间状语名词，指离店结账流程。','核对费用并交回房卡，是酒店 check-out。')],mistakes:[m('The guests completed check-out at arrival, before they received a room or stayed overnight.','The guests completed check-in at arrival, before they received a room.','入住时办理的是 check-in；check-out 是结账离店。')],quiz:[q('check-out',1,1,'At a hotel, check-out usually happens when guests?',['settle the bill and leave','reserve a room for a future trip','first arrive and collect their keys'],'settle the bill and leave','check-out.s1 指结账后离开酒店。'),q('check-out',2,1,'A shop’s check-out may mean?',['the payment process or the place to pay','a room where guests sleep','a doctor’s examination'],'the payment process or the place to pay','词条亦指付款离店或收银柜台。'),q('check-out',3,1,'Which action belongs to hotel check-out?',['returning the key and paying the final bill','asking for a room before arrival','charging a phone overnight'],'returning the key and paying the final bill','交钥匙、结账是酒店离店手续。'),q('check-out',4,1,'A shopper waiting at check-out is waiting to?',['pay for purchases','be examined by a dentist','board a horse-drawn chariot'],'pay for purchases','商店 check-out 是结账区域或环节。')]});
D('check-up',{etymology:e('check-up 由 check 与 up 组成的名词；check 的“检查、核对”义加 up 构成定期或全面检查，尤指医生、牙医或技师为发现问题所做的检查。','check-up'),contexts:[c('check-up.s1','健康管理','Lena booked a dental check-up even though nothing hurt, because her dentist recommends an examination every six months.','虽然没有疼痛，莉娜还是预约了牙科检查，因为牙医建议每六个月检查一次。','Lena booked a dental check-up / even though nothing hurt / because her dentist recommends an examination every six months.','check-up 是 booked 的宾语；dental 限定为牙科检查。','定期由牙医检查以发现问题，符合 check-up.s1。')],mistakes:[m('The mechanic skipped the check-up and inspected nothing, yet claimed to have found and repaired a hidden brake fault.','The mechanic performed a check-up and inspected the brakes to find and repair a hidden fault.','check-up 是实际检查过程，未做任何检查不能称作已检查。')],quiz:[q('check-up',1,1,'A routine medical check-up is intended to?',['look for health problems','collect payment at a supermarket','select actors for a film'],'look for health problems','check-up.s1 是为发现问题所做的体检或复查。'),q('check-up',2,1,'A car may need a check-up at a garage so a mechanic can?',['inspect it for faults','teach it a dance','write a hotel bill'],'inspect it for faults','技师可通过检查排查故障。'),q('check-up',3,1,'Why have a dental check-up when there is no pain?',['to detect problems early','to charge the dentist’s battery','to avoid ever examining the teeth'],'to detect problems early','常规复查可在症状出现前发现问题。'),q('check-up',4,1,'The noun check-up refers to?',['an examination for possible problems','a final payment at a shop only','a musical chord'],'an examination for possible problems','check-up 指检查、体检或复查。')]});
D('checked',{etymology:e('checked 是 check 的过去分词，也作形容词；check 经古法语 eschec“棋局中的将军”进入英语，后有核对、阻止之义，checked 还可指方格图案。','checked'),contexts:[c('checked.s1','服装描述','He wore a checked shirt with alternating blue and white squares, a pattern that remained clear even from across the room.','他穿着一件蓝白相间方格图案的衬衫，即使从房间另一头看图案也很清晰。','He wore a checked shirt / with alternating blue and white squares / a pattern that remained clear even from across the room.','checked 作前置定语修饰 shirt；同位语解释格子图案。','蓝白交替的方格印花体现 checked.s1。')],mistakes:[m('She wore a checked skirt with no squares, stripes, or other repeated pattern at all.','She wore a plain skirt with no squares, stripes, or other repeated pattern at all.','checked 形容格子图案；没有任何重复图案的裙子是 plain。')],quiz:[q('checked',1,1,'A checked fabric has?',['a pattern of squares','only solid black with no pattern','rows of long parallel stripes only'],'a pattern of squares','checked.s1 指方格图案的。'),q('checked',2,2,'A checked box on a form has been?',['marked with a tick or verified','woven from square cloth','charged with electricity'],'marked with a tick or verified','checked.s2 指已核对或打勾。'),q('checked',3,1,'Which garment is checked?',['a shirt with alternating square blocks','a plain shirt with no design','a shirt covered only in small circles'],'a shirt with alternating square blocks','交替方格构成 checked 图案。'),q('checked',4,2,'When a task is checked off a list, it is?',['marked as completed','made into a woven pattern','formally charged with a crime'],'marked as completed','列表上勾选表示已核对或完成。')]});
D('checkmark',{etymology:e('checkmark 由 check 与 mark 组成，指用来表示已核对或已选中的钩形记号；check 的词源经法语与棋局术语有关，mark 则来自古英语 mearc“界线、标记”。','checkmark'),contexts:[c('checkmark.s1','任务清单','A green checkmark appeared beside each safety step after the technician verified that the emergency lights worked.','技师确认应急灯正常后，每项安全步骤旁都出现了绿色勾号。','A green checkmark appeared beside each safety step / after the technician verified that the emergency lights worked.','checkmark 是 appeared 的主语；after 从句说明打勾的条件。','核查后显示勾号，符合 checkmark.s1。')],mistakes:[m('The unfinished task received a checkmark to show that nobody had inspected or selected it.','The unfinished task remained unchecked because nobody had inspected or selected it.','勾号通常标明已核对或已选择；“无人检查”与此矛盾。')],quiz:[q('checkmark',1,1,'A checkmark beside an item usually shows it was?',['checked or selected','rejected without review','turned into a square cloth pattern'],'checked or selected','checkmark.s1 是核对或选择标记。'),q('checkmark',2,1,'Which symbol is a checkmark?',['✓','○','—'],'✓','钩形符号是 checkmark。'),q('checkmark',3,1,'A completed checklist item receives a checkmark to?',['indicate completion','show its price','identify its pronunciation'],'indicate completion','勾号可标记已完成的事项。'),q('checkmark',4,1,'A checkmark is a kind of?',['written or printed mark','musical instrument','chemical compound'],'written or printed mark','checkmark 指钩形记号。')]});
D('checkout',{etymology:e('checkout 是 check out 的合写名词；check“核对、结账”与 out“离开”组合，既指商店收银及付款，也指酒店结账离店。','checkout'),contexts:[c('checkout.s2','酒店服务','The hotel’s checkout time is noon, so guests who leave later must arrange an extension with the front desk.','酒店退房时间是中午，因此晚些离开的客人必须向前台申请延时。','The hotel’s checkout time is noon / so guests who leave later / must arrange an extension with the front desk.','checkout 作名词修饰 time，表示办理退房的规定时间。','酒店离店时间体现 checkout.s2。')],mistakes:[m('Their hotel checkout began before arrival, when they first requested a room for the weekend.','Their hotel check-in began before arrival, when they requested a room for the weekend.','入住预订或抵达手续属于 check-in；checkout 是结账离店。')],quiz:[q('checkout',1,1,'At a supermarket checkout, customers?',['pay for their goods','receive a medical exam','choose actors for a film'],'pay for their goods','checkout.s1 指商店收银台或结账。'),q('checkout',2,2,'A hotel checkout takes place when a guest?',['settles the bill and leaves','first reserves a room','orders breakfast in bed'],'settles the bill and leaves','checkout.s2 指酒店退房离店。'),q('checkout',3,1,'A queue at checkout is a queue of people waiting to?',['pay','be vaccinated','board a chariot'],'pay','商店结账区域常有付款队伍。'),q('checkout',4,2,'Why might a guest ask the front desk about checkout time?',['to know when to leave the hotel','to learn when the room was built','to find the nearest supermarket till'],'to know when to leave the hotel','退房时间规定离开酒店的时间。')]});
D('cheerless',{etymology:e('cheerless 由 cheer 加否定后缀 -less 构成；cheer 经古法语 chiere“面容、情绪”进入英语，cheerless 表示阴郁不快或缺乏热情生气。','cheerless'),contexts:[c('cheerless.s2','接待氛围','The visitors received a cheerless welcome: the staff barely looked up, and nobody offered directions or a greeting.','访客受到冷淡的接待：员工几乎没有抬头，也没人指路或问候。','The visitors received a cheerless welcome / the staff barely looked up / and nobody offered directions or a greeting.','cheerless 作定语修饰 welcome；冒号后的表现说明氛围冷淡。','缺乏热情和友好的接待体现 s2。')],mistakes:[m('The cheerful waiting room was bright, warm, and full of welcoming conversation, yet everyone called it cheerless.','The cheerless waiting room was dark, cold, and silent, with no welcoming conversation.','温暖热闹且友好的空间不符合 cheerless 的阴郁或冷清义。')],quiz:[q('cheerless',1,1,'A cheerless room is likely to feel?',['dark and gloomy','sunny and delightful','electrically charged'],'dark and gloomy','cheerless.s1 指阴郁、令人不快的。'),q('cheerless',2,2,'A cheerless reception lacks?',['warmth and friendliness','a payment counter','a checked pattern'],'warmth and friendliness','cheerless.s2 指缺乏热情和生气。'),q('cheerless',3,1,'Which scene is cheerless?',['a cold, dim room on a rainy afternoon','a lively garden party in sunshine','a crowded birthday table with laughter'],'a cold, dim room on a rainy afternoon','阴暗沉闷的场景符合 s1。'),q('cheerless',4,2,'A cheerless host would probably greet guests?',['without warmth or interest','with a hearty welcome','by giving each a medal'],'without warmth or interest','冷淡无生气的接待体现 s2。')]});
D('chemically',{etymology:e('chemically 由 chemical 加副词后缀 -ly 构成；chemical 经法语来自 medieval Latin chimicus，最终与 alchemy“炼金术”相关，可表示借化学过程或就成分而言。','chemically'),contexts:[c('chemically.s2','材料检测','The two samples look identical, but chemically they differ because one contains a small amount of lead.','两份样品看起来一样，但化学成分不同，其中一份含有少量铅。','The two samples look identical / but chemically they differ / because one contains a small amount of lead.','chemically 修饰 differ，限定比较的是化学组成。','以成分角度比较，体现 chemically.s2。')],mistakes:[m('The untreated mineral was chemically identical to pure water even though laboratory analysis found a different elemental composition.','The untreated mineral was chemically different from pure water because laboratory analysis found a different elemental composition.','元素组成不同就不能在化学成分上完全相同。')],quiz:[q('chemically',1,1,'If a substance is chemically treated, it has been changed by?',['a chemical process','a purely accidental glance','a horse-drawn vehicle'],'a chemical process','chemically.s1 指通过化学方法处理。'),q('chemically',2,2,'Two liquids that look alike but differ chemically have different?',['chemical compositions','prices at checkout','patterns of woven squares'],'chemical compositions','chemically.s2 表示就化学成分而言。'),q('chemically',3,1,'Which action is done chemically?',['using a reagent to remove a stain','brushing dust away with a dry cloth','folding a sheet of paper'],'using a reagent to remove a stain','使用试剂去污是化学处理。'),q('chemically',4,2,'“Chemically pure” primarily concerns?',['what substances and elements are present','how attractive the label looks','how quickly a shop charges customers'],'what substances and elements are present','化学纯度涉及物质的组成。')]});
D('chemosynthesis',{etymology:e('chemosynthesis 由 chemo-“化学”与 synthesis“合成”构成；synthesis 经希腊语 synthesis“放在一起”进入英语，生物学上指生物利用化学反应能量制造有机物。','chemosynthesis'),contexts:[c('chemosynthesis.s1','深海生态','At the hydrothermal vent, bacteria use chemosynthesis to make organic matter from carbon dioxide, powered by reactions involving hydrogen sulfide.','在热液喷口，细菌利用硫化氢参与的化学反应所释放的能量，通过化能合成把二氧化碳转化为有机物。','At the hydrothermal vent / bacteria use chemosynthesis to make organic matter from carbon dioxide / powered by reactions involving hydrogen sulfide.','use chemosynthesis to 表示以此过程制造有机物；powered by 说明能量来源。','能量来自化学反应而非光，符合化能合成定义。')],mistakes:[m('The vent bacteria depended on sunlight for chemosynthesis, so the process stopped whenever the deep ocean was dark.','The vent bacteria used chemical energy for chemosynthesis, so the process could continue without sunlight.','chemosynthesis 利用化学反应能量，而不是依赖阳光。')],quiz:[q('chemosynthesis',1,1,'Chemoautotrophic bacteria perform chemosynthesis using energy from?',['chemical reactions','sunlight alone','sound waves'],'chemical reactions','chemosynthesis.s1 以化学反应能量制造有机物。'),q('chemosynthesis',2,1,'Where might chemosynthesis support an ecosystem without sunlight?',['near a deep-sea hydrothermal vent','on a brightly lit windowsill only','inside a dry paper notebook'],'near a deep-sea hydrothermal vent','深海热液喷口生物可依赖化能合成。'),q('chemosynthesis',3,1,'How does chemosynthesis differ from photosynthesis?',['it uses chemical energy rather than light','it makes no organic matter','it occurs only in flowering plants'],'it uses chemical energy rather than light','关键区别是能量来自化学反应而非光。'),q('chemosynthesis',4,1,'A chemosynthesizing organism makes organic matter by?',['using energy released by chemical reactions','charging a battery in a shop','absorbing no energy at all'],'using energy released by chemical reactions','化学反应提供制造有机物所需能量。')]});

/* A14 checkpoint 2/4: chemurgy–chisel (20 frozen headwords). */
D('chemurgy',{etymology:e('chemurgy 由 chem-“化学”与 -urgy（表示工作、操作）构成，20世纪形成的术语；指把农业原料用于制造工业产品的应用化学。','chemurgy'),contexts:[c('chemurgy.s1','农业工业','The chemurgy project tested whether corn stalks could be processed into adhesives and packaging instead of being burned as waste.','农产化工项目检验能否把玉米秸秆加工成黏合剂和包装材料，而不是当作废物焚烧。','The chemurgy project tested whether corn stalks could be processed into adhesives and packaging / instead of being burned as waste.','chemurgy 作定语修饰 project；whether 从句说明研究的问题。','农业植物原料转制工业品，符合应用化学领域义。')],mistakes:[m('The chemurgy plant made its products entirely from mined iron ore and never used crops or agricultural materials.','The chemurgy plant made industrial products from crops and other agricultural materials.','chemurgy 专指用农业原料制造工业品；只用矿石不符合其对象。')],quiz:[q('chemurgy',1,1,'Chemurgy applies chemistry to make industrial products from?',['agricultural raw materials','only finished metal tools','sunlight with no material input'],'agricultural raw materials','chemurgy.s1 指农业原料的工业化学利用。'),q('chemurgy',2,1,'A chemurgy researcher might study turning crop waste into?',['fuel or packaging','a medieval chariot','a new musical scale'],'fuel or packaging','作物副产品可经农产化工制成工业品。'),q('chemurgy',3,1,'Which project is an example of chemurgy?',['using plant oils to make industrial coatings','counting stars in the chromosphere','checking guests out of a hotel'],'using plant oils to make industrial coatings','农业植物油加工为涂层符合该词义。'),q('chemurgy',4,1,'The first part chemo- in chemurgy points to?',['chemistry','a child','a horse-drawn cart'],'chemistry','chemo- 表示化学，构成术语 chemurgy。')]});
D('cheque',{etymology:e('cheque 是英式拼法，美式通常写 check；作为银行票据名与 check 有相同的法语/棋局词源，后用于表示对账户款项进行核验与支付的书面指令。','cheque'),contexts:[c('cheque.s1','银行业务','She wrote a cheque for the repair bill, signed it, and mailed it to the contractor rather than carrying cash.','她为维修费开了一张支票，签好后寄给承包商，而没有带现金。','She wrote a cheque for the repair bill / signed it / and mailed it to the contractor / rather than carrying cash.','cheque 是 wrote 的宾语；for 引出支票支付的款项。','签发给银行的付款票据体现 cheque.s1。')],mistakes:[m('He wrote a cheque instructing the bank to pay £250, but left the amount and signature completely blank.','He wrote a cheque instructing the bank to pay £250 and signed it before sending it.','支票须写明金额并签名，空白票据并未构成该付款指令。')],quiz:[q('cheque',1,1,'A cheque tells a bank to?',['pay a stated amount from an account','charge a mobile phone','check a patient’s health'],'pay a stated amount from an account','cheque.s1 是通知银行从账户支付指定金额的票据。'),q('cheque',2,1,'Cheque is the usual spelling in?',['British English','American English only','classical Greek'],'British English','英式常写 cheque，美式常写 check。'),q('cheque',3,1,'Which detail normally makes a cheque usable?',['a stated amount and the account holder’s signature','a chariot and two horses','a square checked pattern'],'a stated amount and the account holder’s signature','金额与签名是支票付款指令的重要内容。'),q('cheque',4,1,'A cheque differs from cash because it?',['orders a bank to transfer money from an account','is a form of paper currency issued by every shop','can only be used to charge a battery'],'orders a bank to transfer money from an account','支票要求银行从账户付款。')]});
D('cherry',{etymology:e('cherry 经古法语 cherise、拉丁语 cerasum 来自希腊语 kerasos“樱桃”；词尾 -s 被误析为复数后，英语形成单数 cherry。','cherry'),contexts:[c('cherry.s3','家具设计','The designer chose a cherry finish for the cabinet, matching its bright red-brown surface to the room’s warm palette.','设计师为柜子选了樱桃红饰面，使明亮的红棕色与房间的暖色调相配。','The designer chose a cherry finish for the cabinet / matching its bright red-brown surface / to the room’s warm palette.','cherry 作颜色形容词修饰 finish；matching 分词说明搭配效果。','描述红色饰面而非果实或树，体现 cherry.s3。')],mistakes:[m('The recipe called for fresh cherries, so the cook added cherry branches instead of any fruit.','The recipe called for fresh cherries, so the cook added the small red fruits instead of branches.','食谱需要的是樱桃果实，不是樱桃树枝。')],quiz:[q('cherry',1,1,'A cherry is a small fruit that contains?',['a stone or pit','a large central bone','a layer of feathers'],'a stone or pit','cherry.s1 指核果类的小圆果。'),q('cherry',2,2,'A cherry tree is the tree that?',['produces cherries','grows only pine cones','makes a metal alloy'],'produces cherries','cherry.s2 指结樱桃的树。'),q('cherry',3,3,'A cherry-red scarf is?',['a bright red color like the fruit','a scarf made entirely from fruit','a green-and-white checked pattern'],'a bright red color like the fruit','cherry.s3 表示像樱桃一样的鲜红色。'),q('cherry',4,1,'What would you remove before eating many cherries?',['the hard pit inside each fruit','the tree’s roots','the fruit’s paper wrapper'],'the hard pit inside each fruit','樱桃果实内有硬核。')]});
D('chiaroscuro',{etymology:e('chiaroscuro 借自意大利语 chiaro“明亮”与 oscuro“黑暗”，字面为“明与暗”；在绘画中指以强烈明暗对比塑造体积和戏剧效果。','chiaroscuro'),contexts:[c('chiaroscuro.s1','绘画评论','The portrait’s chiaroscuro places the sitter’s face in a narrow beam of light while the surrounding room disappears into deep shadow.','这幅肖像的明暗对照法把人物面部置于一道窄光中，周围房间则隐入浓重阴影。','The portrait’s chiaroscuro places the sitter’s face in a narrow beam of light / while the surrounding room disappears into deep shadow.','chiaroscuro 是句子主语；while 对照受光面与阴影。','强烈光暗塑造人物面部，体现绘画技法义。')],mistakes:[m('The painter used chiaroscuro by lighting every surface equally, eliminating all shadows and contrast.','The painter used chiaroscuro by setting brightly lit areas against deep shadows.','没有阴影或明暗反差与 chiaroscuro 的核心手法相矛盾。')],quiz:[q('chiaroscuro',1,1,'Chiaroscuro in art relies on contrast between?',['light and dark','sound and silence','warm and cold food'],'light and dark','chiaroscuro.s1 是绘画中强烈的明暗对照。'),q('chiaroscuro',2,1,'An artist might use chiaroscuro to make a figure look?',['three-dimensional through light and shadow','flat by removing every tonal difference','musical by adding half-steps'],'three-dimensional through light and shadow','明暗对照可塑造立体感。'),q('chiaroscuro',3,1,'Which painting most clearly uses chiaroscuro?',['a face lit against a nearly black room','a page filled with evenly bright flat color','a landscape with no tonal contrast'],'a face lit against a nearly black room','亮部与深影的强对比是其特征。'),q('chiaroscuro',4,1,'The word chiaroscuro comes from Italian words for?',['light and dark','child and care','fruit and tree'],'light and dark','意大利语词素 chiaro、oscuro 分别指明亮、黑暗。')]});
D('chic',{etymology:e('chic 是法语借词，19世纪进入英语，表示优雅而时髦；其更早来源不确定，因此不据此声称某个确定词根。','chic'),contexts:[c('chic.s2','时尚评论','The designer’s chic lay in restraint: one sharply cut black coat gave the whole collection more polish than its jeweled pieces.','这位设计师的时髦风范在于克制：一件剪裁利落的黑色外套，比那些镶饰珠宝的作品更显精致。','The designer’s chic lay in restraint / one sharply cut black coat gave the whole collection more polish / than its jeweled pieces.','chic 作名词，表示优雅时髦的风范；冒号后解释其表现。','简洁剪裁带来的优雅风范体现 chic.s2。')],mistakes:[m("The editor called the badly fitted, awkward, old-fashioned outfit chic even though it looked plainly unfashionable.","The editor called the elegant, well-cut outfit chic because it was stylish and attractive.","chic 表示优雅时髦；剪裁糟糕、过时难看的衣服不符合该评价。")],quiz:[q('chic',1,1,'A chic outfit is?',['elegantly fashionable','dirty and unusable','made only of charcoal'],'elegantly fashionable','chic.s1 指优雅时髦、别致好看的。'),q('chic',2,2,'“She has great chic” praises her?',['elegant fashion and style','skill at charging batteries','ability to chide children'],'elegant fashion and style','chic.s2 是优雅时髦的风范。'),q('chic',3,1,'Which design would most likely be called chic?',['a polished, fashionable outfit with simple lines','a broken coat covered in mud','an unfinished medical check-up'],'a polished, fashionable outfit with simple lines','优雅又时髦的设计符合 chic。'),q('chic',4,1,'Chic is borrowed into English from?',['French','Mandarin','Old Norse'],'French','chic 是法语借词。')]});
D('chick',{etymology:e('chick 是 chicken 的缩略形式，先指小鸡，后泛指幼鸟；俚语中也曾用来指年轻女子，但该用法可能显得轻慢或冒犯。','chick'),contexts:[c('chick.s2','野外观察','The robin chicks huddled in the nest while both adult birds carried insects back to feed them.','知更鸟雏鸟挤在巢里，两只成鸟则不断叼昆虫回来喂它们。','The robin chicks huddled in the nest / while both adult birds carried insects back / to feed them.','chicks 是复数主语；while 对比幼鸟与成鸟的动作。','知更鸟的幼鸟而非小鸡，体现 chick.s2。')],mistakes:[m('The adult robin chick fed its own chicks in the nest, though “chick” was meant to identify a fully grown bird.','The adult robin fed its chicks in the nest.','chick 指幼鸟；若描述已成年的知更鸟，应写 adult robin 而非 adult robin chick。')],quiz:[q('chick',1,1,'A chick in a farmyard is?',['a very young chicken','a fully grown horse','a kind of tree'],'a very young chicken','chick.s1 指小鸡。'),q('chick',2,2,'A baby sparrow can also be called a?',['chick','chateau','checkmark'],'chick','chick.s2 可泛指各种鸟的雏鸟。'),q('chick',3,3,'Why can chick for a young woman sound offensive?',['it is slang that may seem dismissive','it is a formal medical diagnosis','it means a respected elected office'],'it is slang that may seem dismissive','chick.s3 是可能冒犯人的口语称呼。'),q('chick',4,1,'Which is a chick?',['a newly hatched chicken','an adult rooster','a nest made of wire'],'a newly hatched chicken','幼小的鸡称为 chick。')]});
D('chide',{etymology:e('chide 源自古英语 cīdan“争吵、责备”，属日耳曼语词；现代常作较正式的动词，表示训斥或严正表示不满。','chide'),contexts:[c('chide.s1','家庭教育','Rather than shout, the teacher gently chided the pupil for interrupting and asked him to let his classmates finish speaking.','老师没有大声喊叫，而是温和地批评学生插话，并请他让同学把话说完。','Rather than shout / the teacher gently chided the pupil for interrupting / and asked him to let his classmates finish speaking.','chided 是过去式；for interrupting 说明责备原因。','因插话受到训斥，体现 chide.s1。')],mistakes:[m('The supervisor chided the employee by congratulating her warmly for following every safety rule.','The supervisor praised the employee warmly for following every safety rule.','遵守规则而受热烈表扬不是 chide；chide 表示责备或批评。')],quiz:[q('chide',1,1,'To chide a child is to?',['scold the child for doing wrong','give the child a prize','ask the child to charge a phone'],'scold the child for doing wrong','chide.s1 指责备做错事的人。'),q('chide',2,2,'A chair may chide a committee by?',['expressing firm formal disapproval','selling the committee a ticket','drawing a checked pattern'],'expressing firm formal disapproval','chide.s2 指以严正言辞表示不赞成。'),q('chide',3,1,'Which action might lead a teacher to chide a pupil?',['repeatedly interrupting classmates','quietly finishing assigned work','returning a lost book'],'repeatedly interrupting classmates','打断同学是可能受责备的行为。'),q('chide',4,2,'A formal letter chided the agency for delays. It?',['firmly criticized the agency','praised the agency’s speed','asked the agency to draw a portrait'],'firmly criticized the agency','正式批评该机构，符合 chide.s2。')]});
D('chiefly',{etymology:e('chiefly 由 chief 加副词后缀 -ly 构成；chief 经古法语来自拉丁语 caput“头”，chiefly 表示占主要部分，也可强调主要出于某种目的。','chiefly'),contexts:[c('chiefly.s2','研究目的','The survey was conducted chiefly to learn why first-year students were leaving the program, not to rank the instructors.','这项调查主要是为了了解一年级学生为何退出项目，而不是给教师排名。','The survey was conducted chiefly to learn why first-year students were leaving the program / not to rank the instructors.','chiefly 修饰 to learn，突出调查的主要目的。','强调开展调查的核心目的，体现 chiefly.s2。')],mistakes:[m("The meal was chiefly made of rice, although it contained no rice at all.","The meal was chiefly made of vegetables, its largest ingredient.","chiefly 表示主要地；食物完全没有米就不能说主要由米制成。")],quiz:[q('chiefly',1,1,'A chiefly rural region is?',['mostly rural','entirely underwater','mainly a place for checkout'],'mostly rural','chiefly.s1 表示主要、大部分。'),q('chiefly',2,2,'If a study was chiefly designed to test safety, its main purpose was?',['to test safety above all','to decorate a laboratory','to charge participants a fee'],'to test safety above all','chiefly.s2 强调主要目的或原因。'),q('chiefly',3,1,'“The audience consisted chiefly of students” means?',['most of the audience were students','no students attended','students were charged with a crime'],'most of the audience were students','chiefly 是“主要由…构成”。'),q('chiefly',4,2,'“She came chiefly to apologize” identifies her?',['main reason for coming','favorite type of fruit','medical examination result'],'main reason for coming','chiefly 可突出行为的主要动机。')]});
D('chieftain',{etymology:e('chieftain 经古法语 chevetain 来自拉丁语 capitaneus“首领、领头人”，源于 caput“头”；英语中指部族、氏族或传统群体的首领。','chieftain'),contexts:[c('chieftain.s1','历史叙述','The clan chieftain called a council of elders to settle the boundary dispute before the harvest began.','氏族首领在收获季开始前召集长老会议，以解决边界争议。','The clan chieftain called a council of elders / to settle the boundary dispute / before the harvest began.','chieftain 是 called 的主语；clan 限定其领导的群体。','氏族的领导者符合 chieftain.s1。')],mistakes:[m('The chieftain was merely a visiting musician with no authority over the tribe or clan.','The chieftain was the leader with authority over the tribe or clan.','没有群体领导权的访客不是 chieftain。')],quiz:[q('chieftain',1,1,'A tribal chieftain is?',['the head of a tribe or clan','a child in a nest','a bank payment slip'],'the head of a tribe or clan','chieftain.s1 指部族或氏族首领。'),q('chieftain',2,1,'Who might settle a dispute for a traditional clan?',['its chieftain','a checkout cashier','a chondrule'],'its chieftain','氏族首领可能主持处理群体事务。'),q('chieftain',3,1,'The ending -tain in chieftain historically relates to?',['a leader or captain','a chemical salt','a young bird'],'a leader or captain','chieftain 经词源发展为群体领导者称谓。'),q('chieftain',4,1,'Which person is a chieftain?',['the elected head of a traditional tribal group','a tourist who has no role in the group','a cashier at a supermarket'],'the elected head of a traditional tribal group','部落群体的首领符合定义。')]});
D('chihuahua',{etymology:e('chihuahua 以墨西哥奇瓦瓦州命名，该犬种与墨西哥相关；英语从地名借用其名，指体型极小的一种犬。','chihuahua'),contexts:[c('chihuahua.s1','宠物照护','The chihuahua wore a warm coat on the cold walk because the tiny dog shivered whenever the wind picked up.','天气寒冷时，这只吉娃娃散步会穿上保暖外套，因为风一大它就发抖。','The chihuahua wore a warm coat on the cold walk / because the tiny dog shivered / whenever the wind picked up.','chihuahua 是 wore 的主语；because 从句解释保暖衣物的原因。','体型极小的犬种在寒风中易发抖，符合词条所指。')],mistakes:[m('The chihuahua was a giant draft horse bred to pull heavy wagons across fields.','The chihuahua was a tiny dog kept as a companion.','吉娃娃是极小型犬，不是拉车的大型马。')],quiz:[q('chihuahua',1,1,'A chihuahua is a breed of?',['very small dog','large water bird','ancient war chariot'],'very small dog','chihuahua.s1 指一种体型极小的狗。'),q('chihuahua',2,1,'The breed’s name comes from a state in?',['Mexico','Iceland','New Zealand'],'Mexico','chihuahua 以墨西哥奇瓦瓦州命名。'),q('chihuahua',3,1,'A tiny chihuahua may need a coat in cold weather because it?',['can feel cold easily','is a kind of flowering plant','has a thick fish scale covering'],'can feel cold easily','小型犬可能较易受寒。'),q('chihuahua',4,1,'Which animal is a chihuahua?',['a small companion dog','a wild chimpanzee','a large flightless bird'],'a small companion dog','吉娃娃属于犬类。')]});
D('chilblain',{etymology:e('chilblain 由 chill“寒冷”与 blain“皮肤水疱、疮”组合而成；blain 是古英语词，现代 chilblain 指受寒冷潮湿后皮肤发炎、发痒的肿胀。','chilblain'),contexts:[c('chilblain.s1','冬季健康','After working outdoors in damp boots, Tomas developed an itchy chilblain on one toe that became red and swollen.','托马斯穿着潮湿的靴子在户外工作后，一根脚趾长了冻疮，发红肿胀并发痒。','After working outdoors in damp boots / Tomas developed an itchy chilblain on one toe / that became red and swollen.','chilblain 是 developed 的宾语；that 从句描述脚趾冻疮。','寒湿后脚趾发红肿痒，符合冻疮定义。')],mistakes:[m('The chilblain was a painless, permanent scar caused by a hot iron on dry skin in summer.','The chilblain was an itchy swelling caused by exposure to cold and damp.','冻疮通常由寒冷潮湿引起且发痒，不是夏季烫伤留下的无痛疤痕。')],quiz:[q('chilblain',1,1,'A chilblain is most often linked to?',['cold and damp exposure','a fresh sunburn in hot weather','an insect’s chitin shell'],'cold and damp exposure','chilblain.s1 是寒湿后出现的皮肤炎症。'),q('chilblain',2,1,'A chilblain may make the skin?',['itchy, red, and swollen','blue and feathered','covered with square cloth'],'itchy, red, and swollen','冻疮常见红肿发痒。'),q('chilblain',3,1,'Which situation could lead to a chilblain?',['cold, damp feet after outdoor work','a warm dry room all day','a brief visit to a sunny beach'],'cold, damp feet after outdoor work','寒冷潮湿的足部容易出现冻疮。'),q('chilblain',4,1,'The word chilblain combines ideas of?',['cold and a skin sore','a child and a musical chord','a bank cheque and a hotel'],'cold and a skin sore','词由 chill 与 blain（皮肤疮）组成。')]});
D('childcare',{etymology:e('childcare 是 child 与 care 组合的复合名词；child 源自古英语 cild，care 源自古英语 caru，合指照料儿童的工作或服务。','childcare'),contexts:[c('childcare.s1','职场福利','The hospital opened an on-site childcare center so nurses on long shifts could leave their children with trained staff nearby.','医院开设了院内托儿中心，让上长班的护士能把孩子交给附近的专业人员照看。','The hospital opened an on-site childcare center / so nurses on long shifts could leave their children / with trained staff nearby.','childcare 作定语修饰 center；so 引出设立托儿服务的目的。','由专业人员照看孩子的服务体现 childcare.s1。')],mistakes:[m('The childcare service looked after office printers and never supervised, fed, or protected any children.','The childcare service supervised and cared for children while their parents worked.','childcare 是照看儿童的服务，不是维修办公设备。')],quiz:[q('childcare',1,1,'Childcare refers to?',['the work or service of looking after children','the repair of a chariot','the charging of a phone'],'the work or service of looking after children','childcare.s1 指照料儿童的工作或服务。'),q('childcare',2,1,'A workplace childcare center helps employees by?',['providing care for their children','checking their bank cheques','teaching them chivalry'],'providing care for their children','托儿中心为员工提供儿童照管服务。'),q('childcare',3,1,'Who might provide childcare?',['a trained nursery worker','a checkout scanner','a chondrite scientist only'],'a trained nursery worker','托儿人员负责照看孩子。'),q('childcare',4,1,'The compound childcare combines child with?',['care','charge','charcoal'],'care','childcare 由 child 与 care 组成。')]});
D('childless',{etymology:e('childless 由 child 加表示“没有”的后缀 -less 构成，直接表示没有儿女；child 源于古英语 cild，-less 源于古英语 -lēas。','childless'),contexts:[c('childless.s1','人物传记','The couple remained childless by choice and devoted much of their time to mentoring young researchers at the institute.','这对夫妇选择不要子女，并把许多时间投入到指导研究所的年轻研究人员上。','The couple remained childless by choice / and devoted much of their time / to mentoring young researchers at the institute.','childless 作主语补语；by choice 明确说明没有子女是自愿选择。','没有儿女这一事实体现 childless.s1。')],mistakes:[m('The childless couple raised three children of their own from birth and described themselves as parents.','The couple with three children raised them from birth and described themselves as parents.','已有三个儿女的人不能称为 childless。')],quiz:[q('childless',1,1,'A childless couple has?',['no son or daughter','several young children','only one adult sibling'],'no son or daughter','childless.s1 意为没有子女。'),q('childless',2,1,'The suffix -less in childless means?',['without','full of','in the past'],'without','-less 表示缺少或没有。'),q('childless',3,1,'Which person is childless?',['an adult with no children','a parent raising two children','a teacher with a large class'],'an adult with no children','是否为教师与子女情况无关；无子女者是 childless。'),q('childless',4,1,'“They remained childless by choice” means they?',['chose not to have children','lost their childcare center','adopted five children'],'chose not to have children','by choice 说明自愿没有子女。')]});
D('chilled',{etymology:e('chilled 是 chill 的过去分词形容词；chill 源自古英语 ciele“寒冷”，可表示使冷却，也可形容态度冷淡，非正式语境还可表示放松。','chilled'),contexts:[c('chilled.s1','餐饮服务','The waiter served chilled soup in small bowls because the recipe is designed to be eaten cold on a hot afternoon.','服务员把冰镇汤盛在小碗里，因为这道菜本来就是为炎热午后冷食设计的。','The waiter served chilled soup in small bowls / because the recipe is designed to be eaten cold / on a hot afternoon.','chilled 作定语修饰 soup；because 解释冷食的缘由。','汤被冷却后端上桌，体现 chilled.s1。')],mistakes:[m('The chilled lemonade was steaming hot straight from the kettle and burned the guest’s tongue.','The chilled lemonade was cold and refreshing after being kept in the refrigerator.','chilled 表示冷却或冰镇，与从水壶刚倒出的滚烫饮料矛盾。')],quiz:[q('chilled',1,1,'Chilled juice is?',['made cold before serving','heated until boiling','woven in a checked pattern'],'made cold before serving','chilled.s1 指冷却、冰镇的。'),q('chilled',2,2,'A chilled response can mean the person sounds?',['unfriendly or emotionally cool','warm and welcoming','scientifically radioactive'],'unfriendly or emotionally cool','chilled.s2 可形容态度冷淡。'),q('chilled',3,2,'Informally, “I’m chilled” may mean?',['I’m calm and relaxed','I have been charged with a crime','I am made of ice'],'I’m calm and relaxed','非正式用法可表示放松、平静。'),q('chilled',4,1,'Which food is chilled?',['a dessert kept cold in a refrigerator','a pie served straight from a hot oven','a steaming bowl fresh from the stove'],'a dessert kept cold in a refrigerator','冷藏后食用的甜点是 chilled food。')]});
D('chilli',{etymology:e('chilli 源自西班牙语 chile，后者借自纳瓦特尔语 chilli，原指辣椒果实；英式拼写常为 chilli，美式常为 chili，也可指辣味炖菜。','chilli'),contexts:[c('chilli.s2','家庭烹饪','For supper, they served chilli with kidney beans, tomatoes, and rice, offering yogurt alongside to soften the heat.','晚餐他们端上加有芸豆、番茄和米饭的辣味炖菜，还配了酸奶来缓和辣味。','For supper / they served chilli with kidney beans, tomatoes, and rice / offering yogurt alongside to soften the heat.','chilli 是 served 的宾语；with 短语列出炖菜配料。','肉豆辣椒炖菜体现 chilli.s2。')],mistakes:[m('She added a sweet cherry to the chilli to make the stew hotter and more peppery.','She added a chilli pepper to the stew to make it hotter and more peppery.','樱桃不是辣椒；增加辣味应加 chilli pepper。')],quiz:[q('chilli',1,1,'A chilli pepper is known for its?',['hot, pungent taste','sweet watery flavor with no heat','hard metal shell'],'hot, pungent taste','chilli.s1 指辛辣的辣椒荚果或其香料。'),q('chilli',2,2,'A bowl of chilli may contain?',['meat, beans, and hot pepper','only chilled fruit juice','a chateau’s stone wall'],'meat, beans, and hot pepper','chilli.s2 是加辣椒的炖菜。'),q('chilli',3,1,'Dried and ground chilli is used as?',['a hot spice','a musical instrument','a hotel checkout receipt'],'a hot spice','辣椒晒干磨碎后可作调味料。'),q('chilli',4,2,'“They made chilli con carne” most likely means they cooked?',['a spicy meat-and-bean stew','a bowl of cold cherry fruit','a chemical solution of chloride'],'a spicy meat-and-bean stew','chilli con carne 是辣味肉豆炖菜。')]});
D('chimp',{etymology:e('chimp 是 chimpanzee 的截短口语形式；chimpanzee 经法语借自非洲语名，现代常用于非正式语境指黑猩猩。','chimp'),contexts:[c('chimp.s1','野生动物保护','The rescued chimp used a branch to reach the fruit, then shared the food with another young ape in the sanctuary.','获救的黑猩猩用树枝够到果子，随后与保护区里的另一只幼猿分享食物。','The rescued chimp used a branch to reach the fruit / then shared the food / with another young ape in the sanctuary.','chimp 是 used 的主语；后文展示该猿类使用工具并与同伴互动。','使用树枝的黑猩猩符合 chimpanzee 的口语简称义。')],mistakes:[m('The chimp was a small songbird with feathers, a beak, and wings for migration.','The chimp was a great ape with hands and no feathers.','chimp 指黑猩猩这种猿类，不是有羽毛的鸟。')],quiz:[q('chimp',1,1,'Chimp is an informal short form of?',['chimpanzee','chiaroscuro','checkmark'],'chimpanzee','chimp.s1 是 chimpanzee 的简称。'),q('chimp',2,1,'A chimp is a kind of?',['great ape','small songbird','flowering tree'],'great ape','黑猩猩属于猿类。'),q('chimp',3,1,'Which behavior might a chimp display?',['using a branch to reach food','laying a hard-shelled egg in a nest','charging a checkout fee'],'using a branch to reach food','黑猩猩会表现出工具使用等行为。'),q('chimp',4,1,'A wildlife sanctuary caring for a chimp is caring for?',['a chimpanzee','a chihuahua puppy only','a chondritic rock'],'a chimpanzee','chimp 就是黑猩猩。')]});
D('Chinese',{etymology:e('Chinese 由 China 加表示所属关系的后缀 -ese 构成；China 的欧洲语言名称源流复杂，可能经波斯语等传播，具体远源存在争议。','Chinese'),contexts:[c('Chinese.s2','语言学习','The translator reads Chinese fluently and checks the original characters before preparing an English version of the contract.','这位译者能流利阅读汉语，并在准备合同英文版前核对原文汉字。','The translator reads Chinese fluently / and checks the original characters / before preparing an English version of the contract.','Chinese 作 reads 的宾语，是语言名；characters 指汉字。','阅读并核对汉字体现 Chinese.s2。')],mistakes:[m('She speaks Chinese, but the sentence claimed this meant she spoke a language unrelated to China or its people.','She speaks Chinese, a language used in China and by Chinese communities worldwide.','Chinese 作语言名时指中国语言，不能说与中国及华人群体无关。')],quiz:[q('Chinese',1,1,'A Chinese person is?',['someone from China or of Chinese origin','anyone who has studied chemistry','a person who lives only in France'],'someone from China or of Chinese origin','Chinese.s1 指中国人或华人。'),q('Chinese',2,2,'Chinese is the name of?',['a language spoken by Chinese people','a type of horse-drawn cart','a form of plant chlorophyll'],'a language spoken by Chinese people','Chinese.s2 指汉语、中文。'),q('Chinese',3,3,'A Chinese calendar is?',['related to China or its people','a calendar made only of checks','a medical check-up'],'related to China or its people','Chinese.s3 是与中国有关的形容词。'),q('Chinese',4,2,'A student learning Chinese may practice reading?',['Chinese characters','chondrules','chivalry codes'],'Chinese characters','汉字是中文书写系统的重要组成部分。')]});
D('chink',{etymology:e('chink 源于中古英语与古法语相关词，可能模拟细小金属声，也可指窄缝；另有指亚裔人的贬损用法，应避免使用。','chink'),contexts:[c('chink.s2','声音描写','The coins chinked softly in her pocket as she climbed the stairs, announcing each step with a faint metallic note.','她上楼时口袋里的硬币轻轻叮当作响，每走一步都会发出微弱的金属声。','The coins chinked softly in her pocket / as she climbed the stairs / announcing each step with a faint metallic note.','chinked 是不及物动词过去式；as 从句说明发声时的动作。','硬币发出的短促轻响体现 chink.s2。')],mistakes:[m('They sealed the chink around the window because the large crack was letting cold air inside.','They sealed the crack around the window because the large opening was letting cold air inside.','chink 通常指小缝；若明确说是 large opening，应使用 crack 或 gap。')],quiz:[q('chink',1,1,'A chink in a wall is?',['a small narrow gap','a large solid pillar','a type of tree fruit'],'a small narrow gap','chink.s1 指小裂缝或缝隙。'),q('chink',2,2,'Coins chink when they?',['make a light metallic ringing sound','turn into a liquid','grow on a tree'],'make a light metallic ringing sound','chink.s2 指发出短促轻微的叮当声。'),q('chink',3,1,'A ray of light through a chink means it passes through?',['a small opening','a solid wall with no gap','a body of water'],'a small opening','窄缝可让光线透过。'),q('chink',4,2,'Which object might chink softly?',['coins touching in a pocket','a thick blanket on a bed','a silent paper sheet'],'coins touching in a pocket','硬币碰撞能发出轻微金属声。')]});
D('chipmunk',{etymology:e('chipmunk 借自奥杰布瓦语或相关阿尔冈昆语名称，经早期北美英语进入使用；指背部有条纹、颊囊能储食的小型地松鼠。','chipmunk'),contexts:[c('chipmunk.s1','公园观察','A chipmunk stuffed sunflower seeds into its cheek pouches, darted beneath the stone wall, and buried some beside a tree root.','一只花栗鼠把葵花籽塞进颊囊，飞快钻到石墙下，并在树根旁埋了一些。','A chipmunk stuffed sunflower seeds into its cheek pouches / darted beneath the stone wall / and buried some beside a tree root.','chipmunk 是并列谓语的主语；颊囊和埋食行为体现其习性。','背部条纹、颊囊储粮的小型地松鼠即花栗鼠。')],mistakes:[m('The chipmunk stored food in a pouch on its back and had smooth skin with no stripes or fur.','The chipmunk stored food in cheek pouches and had fur with dark stripes down its back.','花栗鼠的储食颊囊在脸颊，背部有条纹；不是背上囊袋、光滑无毛。')],quiz:[q('chipmunk',1,1,'A chipmunk is a small kind of?',['ground squirrel','marine mammal','flowering shrub'],'ground squirrel','chipmunk.s1 是小型地松鼠。'),q('chipmunk',2,1,'A chipmunk’s cheek pouches help it?',['carry food','breathe underwater','make a ringing sound'],'carry food','颊囊用于暂存和搬运食物。'),q('chipmunk',3,1,'Which feature helps identify a chipmunk?',['dark stripes down its back','a shell like a chondrite','a pair of wings'],'dark stripes down its back','背部深色条纹是花栗鼠的典型特征。'),q('chipmunk',4,1,'A chipmunk may bury seeds because it?',['stores food for later','is preparing a hotel bill','is making a checked pattern'],'stores food for later','花栗鼠会埋藏食物以备后用。')]});
D('chisel',{etymology:e('chisel 经古法语 cisel 来自晚期拉丁语 cisellum“切削工具”，与 caedere“切”有关；名词指凿子，动词可指雕凿，也可口语指骗取钱财。','chisel'),contexts:[c('chisel.s3','口语表达','The contractor tried to chisel the elderly owner out of an extra deposit by inventing repairs that had never been needed.','承包商编造根本不需要的维修项目，试图骗取这位老房主额外的押金。','The contractor tried to chisel the elderly owner out of an extra deposit / by inventing repairs / that had never been needed.','chisel ... out of money 是“骗取钱财”的口语结构；by 短语交代欺诈手段。','欺诈性地骗取押金，体现 chisel.s3。')],mistakes:[m('She chiseled a refund from the cashier by paying the exact price and receiving no extra money.','She obtained a refund from the cashier by returning the faulty item.','按价付款而未多拿钱不构成骗取；chisel someone out of money 指欺诈性索财。')],quiz:[q('chisel',1,1,'A woodworker’s chisel is?',['a sharp-edged hand tool for cutting wood or stone','a soft brush for painting walls','a metal ring worn on a finger'],'a sharp-edged hand tool for cutting wood or stone','chisel.s1 指手工凿子。'),q('chisel',2,2,'To chisel a shape into stone is to?',['cut or carve it with a chisel','cover it with cloth squares','charge it with electricity'],'cut or carve it with a chisel','chisel.s2 指用凿子雕凿。'),q('chisel',3,3,'To chisel someone out of money is to?',['cheat the person into giving up money','lend the person money without conditions','pay the person an honest refund'],'cheat the person into giving up money','chisel.s3 是骗取钱财的口语用法。'),q('chisel',4,1,'Which tool would a stone carver select?',['a chisel','a cheque','a chihuahua'],'a chisel','雕石工用凿子切削石材。')]});

/* A14 checkpoint 3/4: chitin–Christian (20 frozen headwords). */
D('chitin',{etymology:e('chitin 由法语 chitine 进入英语，源自希腊语 khitōn“外衣、甲壳”；现代指构成节肢动物外骨骼和真菌细胞壁的坚韧多糖。','chitin'),contexts:[c('chitin.s1','生物材料','The beetle’s outer covering contains chitin, a tough material that protects its body while remaining light enough for flight.','甲虫的外层含有几丁质，这种坚韧材料既能保护身体，又足够轻便，不妨碍飞行。','The beetle’s outer covering contains chitin / a tough material that protects its body / while remaining light enough for flight.','chitin 是 contains 的宾语；同位语说明其物质特性与作用。','节肢动物外骨骼中的坚韧多糖即几丁质。')],mistakes:[m('The insect’s chitin was a soft, soluble sugar found only in its blood and absent from the outer shell.','The insect’s chitin was a tough structural polysaccharide in its outer shell.','几丁质构成昆虫外骨骼，并非只存在血液中的柔软可溶糖。')],quiz:[q('chitin',1,1,'Chitin is a structural material found in?',['insect exoskeletons and fungal walls','the feathers of all birds only','human hair as its sole component'],'insect exoskeletons and fungal walls','chitin.s1 指构成节肢动物外骨骼和真菌细胞壁的多糖。'),q('chitin',2,1,'A beetle’s hard outer covering contains?',['chitin','chlorophyll','cellulose nitrate only'],'chitin','昆虫外骨骼的重要成分是几丁质。'),q('chitin',3,1,'Chitin is best described as a?',['tough polysaccharide','liquid metal','kind of animal behavior'],'tough polysaccharide','几丁质是一种坚韧的多糖。'),q('chitin',4,1,'A fungus may use chitin in its?',['cell wall','wing feathers','fruit pit'],'cell wall','真菌细胞壁也可含有几丁质。')]});
D('chivalrous',{etymology:e('chivalrous 由 chivalry 加形容词后缀 -ous 构成；chivalry 经古法语 chevalerie 源自 cheval“马”，历史上关联骑马武士及其礼貌、勇敢与荣誉准则。','chivalrous'),contexts:[c('chivalrous.s1','日常礼仪','The chivalrous stranger held the heavy door for the parent carrying a sleeping child, then stepped aside without expecting thanks.','那位有骑士风度的陌生人为抱着熟睡孩子的家长扶住沉重的门，随后礼貌地让到一旁，并不期待感谢。','The chivalrous stranger held the heavy door / for the parent carrying a sleeping child / then stepped aside without expecting thanks.','chivalrous 修饰 stranger；扶门和礼让展示体贴礼貌。','礼貌、体贴他人的行为体现骑士风度。')],mistakes:[m('The chivalrous guest deliberately shoved the host aside, insulted everyone, and refused to help an injured person.','The discourteous guest deliberately shoved the host aside, insulted everyone, and refused to help an injured person.','粗暴无礼与 chivalrous 所表示的礼貌、体贴相反。')],quiz:[q('chivalrous',1,1,'A chivalrous person shows?',['courtesy, courage, and honorable conduct','deliberate cruelty and selfishness','skill at making a chemical salt'],'courtesy, courage, and honorable conduct','chivalrous.s1 指有骑士风度、礼貌而勇敢。'),q('chivalrous',2,1,'Holding a door for someone carrying a heavy load may seem?',['chivalrous','cheerless','chemically pure'],'chivalrous','体贴礼让可体现骑士风度。'),q('chivalrous',3,1,'Which action is least chivalrous?',['mocking a guest who needs help','offering assistance politely','keeping a promise despite difficulty'],'mocking a guest who needs help','嘲弄求助者并非礼貌、侠义的行为。'),q('chivalrous',4,1,'The adjective chivalrous historically evokes the ideals of?',['medieval knights','deep-sea bacteria','bank clerks'],'medieval knights','该词与中世纪骑士行为准则相关。')]});
D('chivalry',{etymology:e('chivalry 经古法语 chevalerie 来自 cheval“马”，最初指骑士身份与制度，后来也指骑士准则以及礼貌、保护弱者的举止。','chivalry'),contexts:[c('chivalry.s1','历史文化','The museum’s display traces the ideals of chivalry, including loyalty to one’s lord, courage in battle, and courteous conduct.','博物馆展览追溯骑士精神的理想，包括忠于领主、战场勇敢以及待人有礼。','The museum’s display traces the ideals of chivalry / including loyalty to one’s lord / courage in battle / and courteous conduct.','chivalry 是介词 of 的宾语；including 后列出其历史准则。','勇敢、忠诚和礼貌都属于骑士准则。')],mistakes:[m('The code of chivalry praised cowardice, betrayal, and cruelty toward anyone in need.','The code of chivalry praised courage, loyalty, and courteous treatment of those in need.','背叛、懦弱与残酷违背骑士精神的传统理想。')],quiz:[q('chivalry',1,1,'Medieval chivalry was associated with?',['knights’ rules and ideals','the chemical composition of salt','a shop’s payment counter'],'knights’ rules and ideals','chivalry.s1 指骑士制度及其行为准则。'),q('chivalry',2,1,'In modern use, chivalry can refer to?',['polite and protective manners','a young bird’s nest','a fruit’s red color'],'polite and protective manners','该词也指礼貌、保护他人的举止。'),q('chivalry',3,1,'A story of chivalry might emphasize?',['honor and courtesy','deceit and deliberate humiliation','food prices at checkout'],'honor and courtesy','荣誉与礼貌是骑士精神的核心。'),q('chivalry',4,1,'The word chivalry is historically connected with?',['mounted knights and horses','the study of biological clocks','the making of charcoal'],'mounted knights and horses','骑士身份与骑马武士相关。')]});
D('chlorate',{etymology:e('chlorate 由 chlorine 的词干 chlor- 与化学盐类后缀 -ate 构成；化学上指含氯酸根 ClO₃⁻ 的盐，如氯酸钾。','chlorate'),contexts:[c('chlorate.s1','化学实验','The laboratory stored potassium chlorate away from heat and combustible materials because the oxidizing salt can intensify a fire.','实验室把氯酸钾远离热源和可燃物存放，因为这种氧化性盐会加剧火灾。','The laboratory stored potassium chlorate away from heat and combustible materials / because the oxidizing salt can intensify a fire.','chlorate 出现在化合物名 potassium chlorate 中；because 从句说明安全存放原因。','氯酸钾是含 ClO₃⁻ 的氯酸盐。')],mistakes:[m('Sodium chlorate contains the chloride ion Cl⁻ and has no oxygen atoms in its formula.','Sodium chlorate contains the chlorate ion ClO₃⁻, which includes oxygen atoms.','chlorate 的阴离子是 ClO₃⁻；不含氧的 Cl⁻ 是 chloride。')],quiz:[q('chlorate',1,1,'A chlorate contains which group?',['ClO₃⁻','Cl⁻ only','CO₃²⁻'],'ClO₃⁻','chlorate.s1 指含氯酸根 ClO₃⁻ 的盐。'),q('chlorate',2,1,'Potassium chlorate is an example of a?',['chlorate salt','hydrocarbon gas','plant pigment'],'chlorate salt','氯酸钾属于氯酸盐。'),q('chlorate',3,1,'Which formula distinguishes chlorate from chloride?',['ClO₃⁻ includes oxygen','Cl⁻ contains three oxygen atoms','both are exactly Cl₂'],'ClO₃⁻ includes oxygen','氯酸根含三个氧，氯离子不含氧。'),q('chlorate',4,1,'A chemist identifying chlorate would look for?',['the chlorate ion in a salt','a chihuahua breed standard','a checkmark on a form'],'the chlorate ion in a salt','chlorate 是含特定含氧氯阴离子的盐。')]});
D('chloride',{etymology:e('chloride 由 chlor- 与表示化学二元化合物的 -ide 构成；chlor- 来自 chlorine，名称源自希腊语 chlōros“黄绿色”，chloride 指氯与其他元素形成的化合物。','chloride'),contexts:[c('chloride.s1','水质检测','The technician measured chloride in the well water to determine whether road salt had seeped into the supply.','技师测量井水中的氯化物含量，以判断道路融雪盐是否渗入供水。','The technician measured chloride in the well water / to determine whether road salt had seeped into the supply.','chloride 是 measured 的宾语；to determine 表示检测目的。','水中的氯化物离子可作为盐污染的检测指标。')],mistakes:[m('Sodium chloride is a compound of sodium and oxygen, with no chlorine in it.','Sodium chloride is a compound of sodium and chlorine.','氯化钠由钠和氯构成；把它说成含氧而无氯是元素组成错误。')],quiz:[q('chloride',1,1,'A chloride is a compound containing?',['chlorine combined with another element','only hydrogen and carbon','the chlorate group ClO₃ in every case'],'chlorine combined with another element','chloride.s1 指氯与另一元素组成的化合物。'),q('chloride',2,1,'Table salt is commonly known chemically as?',['sodium chloride','potassium chlorate','chlorophyll'],'sodium chloride','食盐的主要成分是氯化钠。'),q('chloride',3,1,'Which statement about chloride is accurate?',['it contains chlorine','it is a kind of animal','it is a music scale'],'it contains chlorine','氯化物的定义核心是含氯。'),q('chloride',4,1,'A chloride measurement in water can help detect?',['dissolved salts containing chlorine','the color of a chateau wall','how loud cicadas sing'],'dissolved salts containing chlorine','氯化物可用于监测水中盐类。')]});
D('chlorine',{etymology:e('chlorine 由 Humphry Davy 于1810年前后命名，来自希腊语 chlōros“淡绿、黄绿色”，描述这种气体的颜色；它是元素，常用于消毒。','chlorine'),contexts:[c('chlorine.s1','饮用水处理','The water plant adds a carefully controlled amount of chlorine to kill harmful microbes before the water reaches households.','自来水厂加入严格控制剂量的氯，在供水到达住户前杀灭有害微生物。','The water plant adds a carefully controlled amount of chlorine / to kill harmful microbes / before the water reaches households.','chlorine 是 adds 的宾语；to kill 表示加氯的目的。','以氯消毒水中的微生物，体现元素用途。')],mistakes:[m('The pool operator removed every trace of chlorine because chlorine is a harmless blue solid with no smell.','The pool operator controlled chlorine levels because chlorine is a reactive yellow-green gas with a sharp smell.','氯是有刺激性气味的黄绿色气体，不是无味蓝色固体。')],quiz:[q('chlorine',1,1,'Chlorine is a chemical?',['element','fruit','type of bird'],'element','chlorine.s1 指化学元素氯。'),q('chlorine',2,1,'Water treatment may use chlorine to?',['kill harmful microbes','make water freeze instantly','add a checked pattern'],'kill harmful microbes','氯可用于水消毒。'),q('chlorine',3,1,'Chlorine gas is typically described as?',['yellow-green with a sharp smell','colorless and sweet like sugar','a solid metal rod'],'yellow-green with a sharp smell','氯气呈黄绿色且有刺激性气味。'),q('chlorine',4,1,'Chlorine differs from chloride because chlorine is?',['the element itself','always a compound with sodium','a kind of organic pigment'],'the element itself','chlorine 是元素名称，chloride 则是含氯化合物。')]});
D('chlorophyll',{etymology:e('chlorophyll 由希腊语 chlōros“绿色”与 phyllon“叶”构成，19世纪形成的科学术语；指植物吸收光能进行光合作用的绿色色素。','chlorophyll'),contexts:[c('chlorophyll.s1','植物生理','When chlorophyll absorbs light in the leaf, the plant can use that energy to convert carbon dioxide and water into sugars.','叶片中的叶绿素吸收光后，植物便能利用这部分能量把二氧化碳和水转化为糖。','When chlorophyll absorbs light in the leaf / the plant can use that energy / to convert carbon dioxide and water into sugars.','chlorophyll 是从句主语；that energy 指被吸收的光能。','叶绿素吸光并支撑光合作用，符合定义。')],mistakes:[m('The plant’s chlorophyll made its leaves yellow by absorbing no light and preventing photosynthesis.','The plant’s lack of chlorophyll made its leaves yellow by limiting photosynthesis.','叶绿素是绿色色素；缺少叶绿素常导致失绿发黄，而不是由它本身造成。')],quiz:[q('chlorophyll',1,1,'Chlorophyll is the green pigment that helps plants?',['absorb light for photosynthesis','digest insects in every species','produce a chondrite'],'absorb light for photosynthesis','chlorophyll.s1 指植物吸光进行光合作用的色素。'),q('chlorophyll',2,1,'A healthy green leaf contains?',['chlorophyll','sodium chloride only','chitin as its only pigment'],'chlorophyll','叶片绿色主要来自叶绿素。'),q('chlorophyll',3,1,'If a plant lacks chlorophyll, its leaves may?',['lose green color and turn yellow','become a checked cloth','make a metallic chink'],'lose green color and turn yellow','缺少叶绿素会导致叶片失绿、发黄。'),q('chlorophyll',4,1,'The word parts in chlorophyll refer to?',['green and leaf','cold and sore','horse and wheel'],'green and leaf','希腊语词素分别为绿色与叶。')]});
D('chlorosis',{etymology:e('chlorosis 来自希腊语 khlōros“黄绿色、苍白”，加医学名词后缀 -osis；现代植物学常指缺叶绿素导致的叶片失绿发黄。','chlorosis'),contexts:[c('chlorosis.s1','园艺诊断','The gardener suspected chlorosis when the young leaves turned yellow between the veins, and tested the soil for unavailable iron.','幼叶的叶脉间发黄时，园丁怀疑是萎黄病，并检测土壤中植物难以吸收的铁。','The gardener suspected chlorosis / when the young leaves turned yellow between the veins / and tested the soil for unavailable iron.','chlorosis 是 suspected 的宾语；when 从句描述典型叶片症状。','叶片因缺少叶绿素发黄，符合植物萎黄病定义。')],mistakes:[m('The plant had chlorosis, shown by deep green leaves rich in chlorophyll and no yellowing anywhere.','The plant had chlorosis, shown by yellow leaves with reduced chlorophyll.','叶绿素充足、叶片深绿与 chlorosis 所指失绿黄化症状相反。')],quiz:[q('chlorosis',1,1,'Plant chlorosis causes leaves to?',['turn yellow as chlorophyll is lacking','grow a checked pattern','produce a metallic sound'],'turn yellow as chlorophyll is lacking','chlorosis.s1 指缺少叶绿素导致的黄化。'),q('chlorosis',2,1,'A gardener seeing yellowing leaves may test for?',['chlorosis','chivalry','chiaroscuro'],'chlorosis','叶片发黄可能是萎黄病。'),q('chlorosis',3,1,'Chlorosis is a disorder of?',['plants','hotel guests','musical instruments'],'plants','词条指植物失绿病症。'),q('chlorosis',4,1,'Which pigment is reduced in chlorosis?',['chlorophyll','charcoal','chlorate'],'chlorophyll','萎黄病由叶绿素不足导致。')]});
D('choked',{etymology:e('choked 是 choke 的过去分词形容词；choke 经古英语 āceocian“窒息、噎住”发展而来，可描述堵塞、噎住，也用于愤怒或情绪哽咽。','choked'),contexts:[c('choked.s2','情绪表达','Her voice was choked with emotion as she thanked the rescue team, and she paused several times before finishing the speech.','她向救援队致谢时声音因激动而哽咽，几次停顿后才讲完。','Her voice was choked with emotion / as she thanked the rescue team / and she paused several times before finishing the speech.','be choked with emotion 是固定搭配；as 从句说明情绪出现的场合。','声音因情绪而发紧，符合 choked.s2。')],mistakes:[m('The drain was choked, so water flowed freely through it without slowing or backing up.','The drain was clear, so water flowed freely through it without slowing or backing up.','若水流畅通无阻，排水口就不是 choked（堵塞的）。')],quiz:[q('choked',1,1,'A choked drain is?',['blocked so water cannot pass easily','newly painted and decorated','fully charged with electricity'],'blocked so water cannot pass easily','choked.s1 指被堵住、难以通过。'),q('choked',2,2,'A voice choked with emotion sounds?',['tight or interrupted by strong feeling','perfectly calm and detached','loud because of an engine'],'tight or interrupted by strong feeling','choked.s2 可形容情绪使声音哽咽。'),q('choked',3,2,'Someone described as choked with anger is?',['very angry or upset','unable to pay at checkout','a young bird'],'very angry or upset','该词也可口语形容恼怒难抑。'),q('choked',4,1,'Traffic choked the road means traffic?',['filled and obstructed the road','made the road electrically charged','turned the road into a chateau'],'filled and obstructed the road','车流堵塞道路体现堵塞义。')]});
D('chomp',{etymology:e('chomp 是 champ 的变体形式，可能带模仿咀嚼声的表达色彩；动词常作 chomp on，表示用力、大声地咬嚼食物。','chomp'),contexts:[c('chomp.s1','餐桌描写','The puppy chomped on the crunchy biscuit with such enthusiasm that crumbs scattered across the kitchen floor.','小狗兴致勃勃地大嚼脆饼干，碎屑都飞散到了厨房地板上。','The puppy chomped on the crunchy biscuit / with such enthusiasm / that crumbs scattered across the kitchen floor.','chomp on 后接被咀嚼的食物；that 从句表示结果。','用力咬嚼脆饼干体现 chomp.s1。')],mistakes:[m('She chomped the soup by chewing each liquid spoonful with her teeth.','She slurped the soup from the spoon.','汤通常用勺喝，不会像固体食物那样 chomp（大声咬嚼）。')],quiz:[q('chomp',1,1,'To chomp on a carrot is to?',['bite and chew it vigorously','boil it until it dissolves','draw it with charcoal'],'bite and chew it vigorously','chomp.s1 指用力咬嚼。'),q('chomp',2,1,'A dog might chomp noisily on?',['a crunchy bone or biscuit','a bowl of clear water','an empty plate'],'a crunchy bone or biscuit','脆硬食物适合用力咀嚼。'),q('chomp',3,1,'Which verb best describes loud, forceful chewing?',['chomp','chide','choreograph'],'chomp','chomp 表示大声地咬嚼。'),q('chomp',4,1,'“He chomped through the sandwich” suggests he?',['ate it with strong bites','painted its picture','checked its bank balance'],'ate it with strong bites','through 表示快速用力地把三明治吃完。')]});
D('chondrite',{etymology:e('chondrite 由希腊语 chondros“谷粒、软骨”经科学术语 chondrule 加矿物名词后缀 -ite 构成；指含球粒的常见石质陨石。','chondrite'),contexts:[c('chondrite.s1','陨石研究','Microscope images showed rounded chondrules inside the chondrite, confirming that the specimen was a primitive stony meteorite.','显微图像显示这块球粒陨石内部有圆形球粒，证实样本是一种原始石质陨石。','Microscope images showed rounded chondrules inside the chondrite / confirming that the specimen was a primitive stony meteorite.','chondrite 是 inside 的宾语；分词短语说明球粒图像所支持的判断。','含有 chondrules 的石质陨石是 chondrite。')],mistakes:[m('The sample was classified as a chondrite even though it was a pure iron meteorite with no silicate grains or chondrules.','The sample was classified as an iron meteorite because it contained no silicate grains or chondrules.','chondrite 是含球粒的石陨石类型；纯铁陨石没有球粒，不符合定义。')],quiz:[q('chondrite',1,1,'A chondrite is a stony meteorite that contains?',['chondrules','chlorophyll','a bank cheque'],'chondrules','chondrite.s1 指含球粒的常见石陨石。'),q('chondrite',2,1,'Where would a scientist find a chondrite?',['among meteorites','in a hotel checkout line','growing on a cherry tree'],'among meteorites','chondrite 是陨石类型。'),q('chondrite',3,1,'A chondrite is distinguished from a pure iron meteorite by its?',['stony material and chondrules','feathers and wings','wooden wheels'],'stony material and chondrules','球粒和石质成分是典型特征。'),q('chondrite',4,1,'A microscope can help identify a chondrite by revealing?',['tiny rounded grains in the rock','a checked fabric pattern','a green leaf pigment'],'tiny rounded grains in the rock','球粒是陨石内部的小圆形颗粒。')]});
D('chondritic',{etymology:e('chondritic 由 chondrite 加形容词后缀 -ic 构成；描述与球粒陨石有关或具有其成分、特征的物质。','chondritic'),contexts:[c('chondritic.s1','行星地质','The researchers compared the asteroid’s chondritic composition with primitive meteorites to estimate what material formed the early solar system.','研究人员将小行星的球粒陨石成分与原始陨石作比较，以估计早期太阳系由何种物质构成。','The researchers compared the asteroid’s chondritic composition / with primitive meteorites / to estimate what material formed the early solar system.','chondritic 作定语修饰 composition；with 引出比较对象。','与原始球粒陨石相似的成分体现 chondritic.s1。')],mistakes:[m('The sample was described as chondritic although it contained only liquid water and no rock or meteorite-like material.','The sample was described as aqueous because it contained liquid water and no meteorite-like rock.','chondritic 表示类似球粒陨石的成分；纯水没有这类岩石物质。')],quiz:[q('chondritic',1,1,'A chondritic composition is?',['related to or resembling chondrites','made only of living cells','a pattern of light and shadow'],'related to or resembling chondrites','chondritic.s1 指与球粒陨石有关或具有其成分。'),q('chondritic',2,1,'Scientists might call primitive meteorite material?',['chondritic','childless','chivalrous'],'chondritic','原始球粒陨石物质可称 chondritic。'),q('chondritic',3,1,'Which comparison is relevant to chondritic matter?',['a primitive stony meteorite','a hotel room checkout time','a bird’s cheek pouch'],'a primitive stony meteorite','球粒陨石为该形容词的参照物。'),q('chondritic',4,1,'The suffix -ic in chondritic makes the word?',['an adjective','a plural noun','a past-tense verb'],'an adjective','-ic 常构成“与…有关的”形容词。')]});
D('chondrule',{etymology:e('chondrule 由希腊语 chondros“谷粒、颗粒”加指小后缀构成，经地质学术语发展而来；指石质陨石中曾熔融、后凝成的小球状颗粒。','chondrule'),contexts:[c('chondrule.s1','显微矿物学','A polished thin section revealed a glassy chondrule surrounded by finer mineral grains embedded in the meteorite.','抛光薄片显露出一个玻璃质球粒，周围是嵌在陨石中的更细矿物颗粒。','A polished thin section revealed a glassy chondrule / surrounded by finer mineral grains / embedded in the meteorite.','chondrule 是 revealed 的宾语；过去分词短语修饰其周围结构。','陨石内部曾熔融凝固的球粒即 chondrule。')],mistakes:[m('The chondrule was a large feathered bird fossil found flying above the meteorite.','The chondrule was a tiny rounded mineral grain enclosed in the meteorite.','chondrule 是陨石内的小球状矿物颗粒，不是鸟类化石。')],quiz:[q('chondrule',1,1,'A chondrule is a tiny rounded grain inside a?',['stony meteorite','chateau garden','chicken egg'],'stony meteorite','chondrule.s1 指石陨石里的小球状颗粒。'),q('chondrule',2,1,'A chondrule was once?',['molten before it cooled','a living insect','a paper bank order'],'molten before it cooled','陨石球粒曾熔融后凝固。'),q('chondrule',3,1,'Which instrument might reveal chondrules in a meteorite?',['a microscope','a checkout scanner','a musical tuner'],'a microscope','小颗粒通常需显微观察。'),q('chondrule',4,1,'A chondrule is associated with?',['meteorite mineral grains','plant photosynthesis','medieval knightly conduct'],'meteorite mineral grains','球粒是陨石中的矿物颗粒。')]});
D('chopsticks',{etymology:e('chopsticks 是 chop 与 sticks 的复合词；英语船员借用 pidgin chop“吃、食物”加 sticks“棍子”形成该名，表示用于夹取食物的一双细长筷子。','chopsticks'),contexts:[c('chopsticks.s1','餐桌礼仪','She lifted the dumpling with chopsticks, keeping the two sticks aligned so the soft wrapper would not tear.','她用筷子夹起饺子，让两根筷子保持对齐，以免弄破柔软的外皮。','She lifted the dumpling with chopsticks / keeping the two sticks aligned / so the soft wrapper would not tear.','with chopsticks 表示工具；so 从句说明对齐筷子的目的。','两根细棍夹取食物，是筷子的用法。')],mistakes:[m('He ate rice with a single chopstick, using the lone stick as a spoon to scoop every grain.','He ate rice with chopsticks, using the pair of sticks to pick up the grains.','chopsticks 指一双筷子，通常两根配合使用；单根不是一双。')],quiz:[q('chopsticks',1,1,'Chopsticks are?',['a pair of slender sticks used to lift food','one large spoon for stirring soup','a fork with four metal prongs'],'a pair of slender sticks used to lift food','chopsticks.s1 指夹食物的一双细棍。'),q('chopsticks',2,1,'How many sticks make a pair of chopsticks?',['two','one','five'],'two','筷子由两根配合使用。'),q('chopsticks',3,1,'A diner might use chopsticks to?',['pick up noodles','write a bank cheque','measure chlorophyll'],'pick up noodles','筷子常用于夹取面条等食物。'),q('chopsticks',4,1,'Which tool is not chopsticks?',['a single soup spoon','two slender eating sticks','a matched pair of food sticks'],'a single soup spoon','勺子不是用于夹食物的一双筷子。')]});
D('chordate',{etymology:e('chordate 由 chord- 与生物分类后缀 -ate 构成；chord 在此经希腊语 khordē“弦、索”关联 notochord“脊索”，指脊索动物门成员或其特征。','chordate'),contexts:[c('chordate.s1','动物学课堂','A fish is a chordate because it belongs to Chordata, the phylum whose members possess a notochord at some stage of development.','鱼类属于脊索动物，因为它隶属脊索动物门；该门动物在发育的某个阶段具有脊索。','A fish is a chordate / because it belongs to Chordata / whose members possess a notochord at some stage of development.','chordate 作表语名词；because 从句解释分类依据。','鱼类属脊索动物门，体现 chordate.s1。')],mistakes:[m('A chordate is defined by never having a notochord or nerve cord at any stage of life.','A chordate has a notochord and dorsal nerve cord at some stage of development.','脊索动物的分类特征包括某阶段具有脊索等结构，原句把定义完全反转。')],quiz:[q('chordate',1,1,'A chordate is an animal in the phylum?',['Chordata','Chlorophyta','Chordless'],'Chordata','chordate.s1 指脊索动物门成员。'),q('chordate',2,2,'A chordate animal is one that?',['belongs to or has features of the chordates','has no developmental stage','is a kind of string instrument'],'belongs to or has features of the chordates','chordate.s2 可作形容词，表示属于脊索动物或有脊索。'),q('chordate',3,1,'Which group includes fishes and mammals?',['chordates','only insects with chitin','only plants with chlorophyll'],'chordates','鱼类和哺乳动物都属于脊索动物。'),q('chordate',4,2,'A chordate feature may include a?',['notochord at some developmental stage','cherry pit','hotel checkout desk'],'notochord at some developmental stage','脊索是该类动物的关键发育特征。')]});
D('choreograph',{etymology:e('choreograph 由 choreo-“舞蹈”与 -graph“书写、描绘”构成，19世纪从 choreography 反向形成动词；指设计并指导舞蹈或演出的动作顺序。','choreograph'),contexts:[c('choreograph.s1','舞台制作','The director asked Nia to choreograph the opening number so that twelve dancers could cross the stage without colliding.','导演请妮娅为开场舞编舞，让十二名舞者能穿过舞台而不互相碰撞。','The director asked Nia to choreograph the opening number / so that twelve dancers could cross the stage / without colliding.','ask sb to choreograph sth 表示请某人为节目编排动作；so that 引出目的。','为舞台节目设计舞步及走位，符合 choreograph.s1。')],mistakes:[m('The choreographer choreographed the dance by choosing costumes only and arranging no movements or steps.','The choreographer designed the dancers’ steps and movement sequence for the dance.','choreograph 指编排动作顺序，仅选服装而不设计动作不构成编舞。')],quiz:[q('choreograph',1,1,'To choreograph a dance is to?',['plan and direct its sequence of movements','write its ticket prices','measure the performers’ height only'],'plan and direct its sequence of movements','choreograph.s1 指设计并指导舞蹈动作。'),q('choreograph',2,1,'A director might choreograph a fight scene to?',['plan how performers move safely and clearly','choose a hotel checkout time','make a chemical solution'],'plan how performers move safely and clearly','动作设计可用于舞台打斗场面。'),q('choreograph',3,1,'Which task is choreography?',['arranging steps and formations for dancers','selecting a chateau’s roof tiles','checking a bank account'],'arranging steps and formations for dancers','舞步和队形编排属于编舞。'),q('choreograph',4,1,'The verb choreograph is about organizing?',['movement in a performance','chemical elements in a salt','dates in a historical chronology'],'movement in a performance','编舞安排的是演出动作。')]});
D('choreographer',{etymology:e('choreographer 由 choreography 加表示人的后缀 -er 构成；choreography 来自希腊语 khoreia“舞蹈”与 -graphia“书写”，指编舞者或排练指导。','choreographer'),contexts:[c('choreographer.s2','舞团排练','The choreographer coached the dancers through the difficult transition, repeating the rehearsal until their timing matched the music.','舞蹈编导带演员练习困难的衔接段落，反复排练直到动作节奏与音乐相合。','The choreographer coached the dancers through the difficult transition / repeating the rehearsal / until their timing matched the music.','choreographer 是 coached 的主语；排练指导体现其 s2 职责。','训练演员、指导排练，符合 choreographer.s2。')],mistakes:[m("The choreographer coached the dancers by never speaking to them or giving any direction.","The choreographer coached the dancers by demonstrating steps and directing their practice.","指导舞者需要提供动作示范或排练方向；完全不沟通也不给指导，与 coach 的含义相矛盾。")],quiz:[q('choreographer',1,1,'A choreographer designs?',['the steps and movements of a dance','a hotel’s payment counter','the chemical formula of chitin'],'the steps and movements of a dance','choreographer.s1 指设计舞蹈动作的人。'),q('choreographer',2,2,'A choreographer directing rehearsal may?',['train dancers and coach their timing','sell chondritic rock samples','check out a library book only'],'train dancers and coach their timing','choreographer.s2 指训练舞者并指导排练的人。'),q('choreographer',3,1,'Who decides how dancers cross the stage?',['the choreographer','the checkmark','the chihuahua'],'the choreographer','编舞者设计舞者动作和走位。'),q('choreographer',4,2,'A choreographer working with a troupe during practice is?',['guiding rehearsals','charging the dancers for electricity','identifying a plant disease'],'guiding rehearsals','指导舞团排练体现 s2。')]});
D('choreographic',{etymology:e('choreographic 由 choreography 加形容词后缀 -ic 构成；choreography 源自希腊语表示舞蹈与书写的词素，choreographic 指与编舞艺术有关。','choreographic'),contexts:[c('choreographic.s1','演出评论','The reviewer praised the choreographic design, noting how the dancers’ circular patterns echoed the turning movement of the set.','评论家称赞了编舞设计，并指出舞者的圆形队形呼应了布景的旋转动作。','The reviewer praised the choreographic design / noting how the dancers’ circular patterns / echoed the turning movement of the set.','choreographic 修饰 design；noting 引出评论家指出的具体舞蹈安排。','队形与动作的设计属于编舞艺术。')],mistakes:[m('The choreographic plan contained no dance movements, steps, formations, or other performance arrangement.','The lighting plan contained no dance movements, steps, formations, or other performance arrangement.','没有舞蹈动作或队形安排的计划不属于 choreographic。')],quiz:[q('choreographic',1,1,'Choreographic work is connected with?',['the art of arranging dances','the study of bank cheques','the chemistry of chlorine'],'the art of arranging dances','choreographic.s1 表示与编舞有关。'),q('choreographic',2,1,'A choreographic pattern might describe?',['dancers’ steps and formations','the shape of a chondrule','the price at a checkout'],'dancers’ steps and formations','舞者的动作与队形属于编舞设计。'),q('choreographic',3,1,'Which adjective belongs in “___ design for the ballet”?',['choreographic','childless','chlorotic'],'choreographic','芭蕾舞的动作设计可称 choreographic design。'),q('choreographic',4,1,'The suffix -ic in choreographic helps form?',['an adjective meaning related to choreography','a plural of choreographer','a past-tense verb'],'an adjective meaning related to choreography','-ic 构成“与…有关的”形容词。')]});
D('choreography',{etymology:e('choreography 由希腊语 khoreia“合唱舞蹈”与 -graphia“书写、记录”构成，经法语进入英语；指编舞艺术或设计完成的一套舞蹈动作。','choreography'),contexts:[c('choreography.s1','现代舞演出','The choreography begins with a still line, then gradually breaks into overlapping duets that fill the stage with movement.','这套编舞从静止的一列开始，随后逐渐变为彼此交错的双人舞，让舞台充满动作。','The choreography begins with a still line / then gradually breaks into overlapping duets / that fill the stage with movement.','choreography 是 begins 的主语；后文描述动作序列如何展开。','一套舞蹈动作及其创作安排体现 choreography.s1。')],mistakes:[m('The choreography of the piece consisted only of its ticket list and the theater’s seating chart.','The choreography of the piece consisted of the dancers’ planned steps and movement sequence.','票单与座位图不属于舞蹈动作设计；choreography 指编舞或成套舞步。')],quiz:[q('choreography',1,1,'Choreography is the art of?',['creating sequences of dance movements','testing drinking water for chloride','writing a bank cheque'],'creating sequences of dance movements','choreography.s1 指编舞艺术及舞蹈动作序列。'),q('choreography',2,1,'A ballet’s choreography may include?',['steps, formations, and movement patterns','only the theater’s ticket prices','the actors’ tax bills'],'steps, formations, and movement patterns','编舞涵盖舞步、队形及动作安排。'),q('choreography',3,1,'A single finished dance sequence can also be called?',['choreography','chlorosis','charcoal'],'choreography','该词也可指某一套已编好的舞蹈动作。'),q('choreography',4,1,'Who usually creates choreography?',['a choreographer','a water-treatment operator','a bank teller'],'a choreographer','编舞者创作 choreography。')]});
D('Christian',{etymology:e('Christian 经拉丁语 christianus 与希腊语 christianos 来自 Christos“受膏者”，指基督徒，也作形容词表示与基督教或基督徒有关；作“正派人”属口语。','Christian'),contexts:[c('Christian.s3','宗教文化','The community organized a Christian charity concert, inviting local choirs to raise money for families displaced by the flood.','这个社区组织了一场基督教慈善音乐会，邀请当地合唱团为洪灾流离失所的家庭筹款。','The community organized a Christian charity concert / inviting local choirs to raise money / for families displaced by the flood.','Christian 作定语修饰 charity concert；邀请合唱团说明活动形式。','该活动与基督教群体或其机构有关，体现 Christian.s3。')],mistakes:[m('The article described a Christian festival as unrelated to Christianity, Christians, or any Christian tradition.','The article described a Christian festival as related to Christianity and its traditions.','形容词 Christian 表示与基督教或基督徒相关，不能同时断言毫无关系。')],quiz:[q('Christian',1,1,'A Christian is a person who follows?',['the teachings of Christianity','the rules of a chariot race','a plant’s chemical cycle'],'the teachings of Christianity','Christian.s1 指基督徒。'),q('Christian',2,2,'Informally, calling someone a Christian may mean the person is?',['decent and kind','a type of meteorite','always a church official'],'decent and kind','Christian.s2 有时口语表示正派善良的人。'),q('Christian',3,3,'A Christian holiday is one?',['related to Christianity','related only to plant chlorophyll','used to check a hotel bill'],'related to Christianity','Christian.s3 表示与基督教有关。'),q('Christian',4,1,'A Christian congregation consists of?',['people who follow Christianity','only professional dancers','chemistry students studying chlorate'],'people who follow Christianity','基督徒是信仰基督教的人。')]});

/* A14 checkpoint 4/4: Christianity–cinematograph (20 frozen headwords). */
D('Christianity',{etymology:e('Christianity 由 Christian 加名词后缀 -ity 构成；Christian 源自希腊语 christianos“基督的追随者”，最终关联 Christos“受膏者”，指基督教及其信仰精神或信徒整体。','Christianity'),contexts:[c('Christianity.s1','宗教研究','The historian wrote that Christianity spread through both formal missions and the everyday networks of merchants and families.','历史学家写道，基督教既通过正式传教活动传播，也借助商人和家庭的日常网络扩展。','The historian wrote that Christianity spread through both formal missions / and the everyday networks of merchants and families.','Christianity 是 that 从句主语；both…and 并列两种传播途径。','描述宗教信仰及其传播，体现 Christianity.s1；整体信仰传统亦可对应 s2。')],mistakes:[m('The essay defined Christianity as a religion unrelated to Jesus, Christian belief, or Christians as a community.','The essay defined Christianity as the religion based on Jesus’s life and teachings and the wider Christian tradition.','Christianity 的核心是以耶稣生平教导为基础的宗教，不能说与之无关。')],quiz:[q('Christianity',1,1,'Christianity is the religion based on the life and teachings of?',['Jesus Christ','a medieval chieftain','an ancient meteorite'],'Jesus Christ','Christianity.s1 指以耶稣生平与教导为基础的宗教。'),q('Christianity',2,2,'“The spirit of Christianity” refers to?',['the beliefs or values associated with Christians','a chemical gas in a church','the price of a Bible at checkout'],'the beliefs or values associated with Christians','Christianity.s2 可指基督教精神。'),q('Christianity',3,1,'A historian studying Christianity would examine?',['the development of the Christian religion','how chondrules form','how a chisel cuts stone'],'the development of the Christian religion','基督教的历史与教义属于宗教史研究。'),q('Christianity',4,2,'Christianity as a community may refer to?',['Christians considered as a whole','a single church building only','a musical arrangement for dancers'],'Christians considered as a whole','该词也可指基督徒整体。')]});
D('Christmas',{etymology:e('Christmas 缩自古英语 Crīstes mæsse“基督弥撒”，即纪念基督诞生的弥撒；前部来自 Christ，后部 mass 指教会礼仪，节日定于12月25日。','Christmas'),contexts:[c('Christmas.s1','节日习俗','On Christmas morning, the family exchanged small gifts before visiting neighbors who had spent the holiday alone.','圣诞节早晨，一家人先互赠小礼物，然后去探望独自过节的邻居。','On Christmas morning / the family exchanged small gifts / before visiting neighbors / who had spent the holiday alone.','Christmas 作节日名称；before visiting 表示探望发生在互赠礼物之后。','十二月节日及相关假期活动体现 Christmas.s1。')],mistakes:[m('Christmas is celebrated every July 4 as a festival unrelated to the birth of Jesus or the winter holiday season.','Christmas is celebrated on December 25 to mark the Christian festival and the holiday season around it.','Christmas 通常在12月25日庆祝，与耶稣诞生纪念及其假期有关。')],quiz:[q('Christmas',1,1,'Christmas is traditionally celebrated on?',['December 25','April 1','July 4'],'December 25','Christmas.s1 指每年12月25日的节日。'),q('Christmas',2,1,'Christmas commemorates the birth of?',['Jesus','a chieftain','a famous cellist'],'Jesus','该节日纪念耶稣诞生。'),q('Christmas',3,1,'A Christmas holiday may include?',['celebrations and time off around December 25','a summer exam every July','a routine dental check-up only'],'celebrations and time off around December 25','Christmas 也指圣诞前后的假期时段。'),q('Christmas',4,1,'The first part of Christmas refers to?',['Christ','chitin','chic'],'Christ','Christmas 源于“基督的弥撒”。')]});
D('chromatic',{etymology:e('chromatic 源自希腊语 chrōmatikos“与颜色有关”，来自 chrōma“颜色”；在音乐中也指使用半音音程的。','chromatic'),contexts:[c('chromatic.s2','音乐理论','The chromatic passage climbs by semitones, adding tension before the melody returns to the simpler major scale.','这段半音进行以半音逐级上行，在旋律回到较简单的大调音阶前增添了紧张感。','The chromatic passage climbs by semitones / adding tension / before the melody returns to the simpler major scale.','chromatic 修饰 passage；by semitones 说明半音进行方式。','音乐音符按半音移动，体现 chromatic.s2。')],mistakes:[m('The chromatic scale omitted every semitone and moved only in whole tones from beginning to end.','The chromatic scale moved through successive semitones.','半音阶以连续半音构成；完全省略半音与 chromatic 的音乐义相反。')],quiz:[q('chromatic',1,1,'A chromatic painting is concerned with?',['color','hotel checkout','tribal leadership'],'color','chromatic.s1 指与颜色有关或色彩丰富。'),q('chromatic',2,2,'A chromatic musical passage moves by?',['semitones','whole weeks','chemical reactions'],'semitones','chromatic.s2 是音乐中的半音进行。'),q('chromatic',3,1,'A rich chromatic palette contains?',['many colors','only one unchanging note','no color at all'],'many colors','丰富色彩体现 chromatic.s1。'),q('chromatic',4,2,'A musician playing a chromatic scale uses?',['each successive semitone','only two notes separated by an octave','no pitched notes'],'each successive semitone','半音阶逐个经过相邻半音。')]});
D('chromatophore',{etymology:e('chromatophore 由希腊语 chrōma“颜色”与 phoros“承载”构成；生物学中指含色素的细胞，如乌贼和变色龙皮肤中的色素细胞，也可指植物细胞的色素体。','chromatophore'),contexts:[c('chromatophore.s1','动物生理','When the cuttlefish expanded dark chromatophores in its skin, its mottled pattern became visible against the pale sand.','乌贼皮肤里的深色色素细胞扩展时，斑驳的图案便在浅色沙地背景下显现出来。','When the cuttlefish expanded dark chromatophores in its skin / its mottled pattern became visible / against the pale sand.','chromatophores 是 expanded 的宾语；when 从句表示图案显现的条件。','乌贼皮肤中含色素、可改变外观的细胞即 chromatophores。')],mistakes:[m('The chromatophore was an empty blood vessel with no pigment and no role in coloration.','The chromatophore was a pigment-bearing cell involved in coloration.','chromatophore 是含色素的细胞，不是无色素的血管。')],quiz:[q('chromatophore',1,1,'A chromatophore is a cell or cell body that contains?',['pigment','a bank cheque','a horse’s saddle'],'pigment','chromatophore.s1 指含色素的细胞或载色体。'),q('chromatophore',2,1,'Chromatophores help a squid change its?',['skin coloration or pattern','chitin into a chariot','hotel checkout time'],'skin coloration or pattern','乌贼皮肤色素细胞与颜色变化相关。'),q('chromatophore',3,1,'The word parts refer to?',['color and carrying','cold and skin sore','dance and writing'],'color and carrying','chroma 表示颜色，-phore 表示承载者。'),q('chromatophore',4,1,'Where might an animal have chromatophores?',['in its skin','in a bank account','on a paper ticket'],'in its skin','乌贼或变色龙的皮肤含色素细胞。')]});
D('chromosphere',{etymology:e('chromosphere 由希腊语 chrōma“颜色”与 sphaira“球体”构成；天文学中指太阳明亮光球层之外、色彩偏红的薄气体层，日食时可见。','chromosphere'),contexts:[c('chromosphere.s2','日食观测','During totality, observers saw a thin reddish ring around the eclipsed Sun, the chromosphere briefly visible beyond the Moon’s edge.','全食阶段，观测者看见被遮挡太阳周围的一圈淡红薄环；色球层短暂地显现在月缘之外。','During totality / observers saw a thin reddish ring around the eclipsed Sun / the chromosphere briefly visible beyond the Moon’s edge.','chromosphere 是同位语，解释日食期间可见的红色环带。','日食时太阳边缘的淡红光环对应 chromosphere.s2。')],mistakes:[m('The chromosphere is the solid rocky core of the Moon, visible every night as a green disk.','The chromosphere is a thin gas layer around the Sun, sometimes seen as a reddish ring during an eclipse.','色球层是太阳周围的气体层，不是月球岩石内核。')],quiz:[q('chromosphere',1,1,'The chromosphere is a layer of gas around?',['the Sun','a chihuahua','a cherry tree'],'the Sun','chromosphere.s1 指太阳光球层上方的薄气层。'),q('chromosphere',2,2,'During an eclipse, the chromosphere may appear as?',['a reddish ring around the Sun','a square mark on a form','a dark meteorite grain'],'a reddish ring around the Sun','chromosphere.s2 指日食时可见的红色光环。'),q('chromosphere',3,1,'The word chromosphere combines ideas of?',['color and sphere','child and care','wood and charcoal'],'color and sphere','词由表示颜色和球体的词素构成。'),q('chromosphere',4,1,'The chromosphere lies above the Sun’s?',['bright visible surface','ocean floor','solid lunar core'],'bright visible surface','色球层位于太阳明亮表面之上。')]});
D('chronical',{etymology:e('chronical 是较少见的 chronic 变体，二者都关联希腊语 khronikos“与时间有关”，来自 khronos“时间”；形容病症长期持续或问题长期难改。','chronical'),contexts:[c('chronical.s2','社会问题','The report called housing insecurity a chronical problem because it had persisted across several administrations despite repeated policy changes.','报告称住房不稳定是一个长期难改的问题，因为尽管政策多次变动，它仍跨越数届政府持续存在。','The report called housing insecurity a chronical problem / because it had persisted across several administrations / despite repeated policy changes.','chronical 修饰 problem；because 从句说明其长期延续的根据。','跨越多年且难以解决，体现 chronical.s2。')],mistakes:[m('The chronical illness began this morning and disappeared completely before lunch, with no lasting symptoms.','The brief illness began this morning and disappeared completely before lunch, with no lasting symptoms.','chronical 表示长期持续；数小时内彻底消失不符合慢性义。')],quiz:[q('chronical',1,1,'A chronical illness is one that?',['lasts a long time and is hard to cure','begins and ends in a few minutes','is always caused by a chondrite'],'lasts a long time and is hard to cure','chronical.s1 指长期难愈的疾病。'),q('chronical',2,2,'A chronical social problem is?',['long-standing and difficult to change','a one-time minor event','a problem about musical half-steps'],'long-standing and difficult to change','chronical.s2 指积久难改的问题或习惯。'),q('chronical',3,1,'Which condition is most plausibly chronical?',['a persistent illness lasting for years','a sneeze lasting one second','a brief paper cut that heals overnight'],'a persistent illness lasting for years','长期持续的疾病符合其医学义。'),q('chronical',4,2,'A chronical habit is?',['a long-established habit that is hard to change','a choice made once and never repeated','a type of biological clock'],'a long-established habit that is hard to change','积久难改的习惯体现 s2。')]});
D('chronobiology',{etymology:e('chronobiology 由希腊语 chronos“时间”与 biology“生物学”构成；研究生物体内的时间组织，包括昼夜节律、季节节律及其机制。','chronobiology'),contexts:[c('chronobiology.s1','生物医学研究','Chronobiology researchers compared hormone levels at dawn and midnight to learn how the body’s daily rhythm affects sleep.','时间生物学研究人员比较黎明与午夜的激素水平，以了解人体昼夜节律如何影响睡眠。','Chronobiology researchers compared hormone levels at dawn and midnight / to learn how the body’s daily rhythm affects sleep.','chronobiology 作定语修饰 researchers；对比不同时点以研究节律作用。','研究生物体时间节律及其影响，符合 chronobiology.s1。')],mistakes:[m('Chronobiology studies only the shape of fossils and has nothing to do with timing or rhythms in living things.','Chronobiology studies timing and rhythms in living things, including daily cycles.','chronobiology 研究生物节律，不是只研究化石形状。')],quiz:[q('chronobiology',1,1,'Chronobiology studies?',['timing and rhythms in living organisms','the design of dance steps','the chemistry of bank notes'],'timing and rhythms in living organisms','chronobiology.s1 是研究生物时间节律的学科。'),q('chronobiology',2,1,'A chronobiologist might examine?',['circadian sleep patterns','a chateau’s stonework','a chisel’s sharpness'],'circadian sleep patterns','昼夜节律是时间生物学的重要研究对象。'),q('chronobiology',3,1,'The prefix chrono- refers to?',['time','color','food'],'time','chrono- 表示时间。'),q('chronobiology',4,1,'Seasonal breeding cycles are relevant to?',['chronobiology','chiaroscuro','chivalry'],'chronobiology','季节性生物节律属于其研究范围。')]});
D('chronologically',{etymology:e('chronologically 由 chronological 加副词后缀 -ly 构成；chronological 来自希腊语 chronos“时间”，表示按照事件发生或日期的先后顺序排列。','chronologically'),contexts:[c('chronologically.s1','档案整理','The archivist arranged the letters chronologically, from the earliest dated note to the final message written decades later.','档案管理员按时间顺序整理这些信件，从日期最早的便条排到几十年后写下的最后一封信。','The archivist arranged the letters chronologically / from the earliest dated note / to the final message written decades later.','chronologically 修饰 arranged，from…to…标出由早到晚的次序。','依据日期先后排列，体现 chronologically.s1。')],mistakes:[m("Events were arranged chronologically by color instead of by when they happened.","Events were arranged chronologically from the earliest date to the latest.","chronologically 表示按事件发生时间排列；按颜色而非日期排序不符合该副词义。")],quiz:[q('chronologically',1,1,'To list events chronologically is to list them by?',['the time they happened','their color','their ticket price'],'the time they happened','chronologically.s1 指依照时间先后排列。'),q('chronologically',2,1,'A chronologically ordered biography usually begins with?',['the earliest events','the author’s favorite scene regardless of date','the last event and jumps randomly'],'the earliest events','通常从较早事件依序写到较晚事件。'),q('chronologically',3,1,'A timeline is arranged?',['chronologically','chemically','chivalrously'],'chronologically','时间线按时间排列。'),q('chronologically',4,1,'Which ordering is chronological?',['1998, 2005, 2012','2012, 1998, 2005 in random order','red, blue, green by hue'],'1998, 2005, 2012','日期由早到晚，符合 chronologically。')]});
D('chronology',{etymology:e('chronology 由希腊语 chronos“时间”与 -logia“研究、论述”构成；既指按日期排列的事件年表，也指考订和排列史事年代的学科。','chronology'),contexts:[c('chronology.s2','历史考证','The chronology of the settlement was revised after archaeologists found coins whose dates placed the earliest houses a century later.','考古学家发现了年代更晚的硬币后，修订了这处聚落的年代学判断；硬币表明最早房屋晚了一个世纪。','The chronology of the settlement was revised / after archaeologists found coins / whose dates placed the earliest houses a century later.','chronology 是 revised 的主语，指对年代先后的考订。','依据考古证据重新判断年代顺序，体现 chronology.s2。')],mistakes:[m('The chronology listed events in random order and gave no dates, so readers could not tell what happened first.','The chronology listed events by date so readers could tell what happened first.','chronology 年表应按事件发生日期排列，而非毫无次序。')],quiz:[q('chronology',1,1,'A chronology of a war is?',['a dated list of events in sequence','a list of actors chosen for a film','a chemical formula'],'a dated list of events in sequence','chronology.s1 指按发生先后排列的大事记。'),q('chronology',2,2,'The academic study of dating past events is?',['chronology','chomp','childcare'],'chronology','chronology.s2 指按日期考订排列史事的学问。'),q('chronology',3,1,'A reader uses a chronology to learn?',['which event came before another','how to play a cello','how to store a chihuahua'],'which event came before another','年表呈现事件先后关系。'),q('chronology',4,2,'A historian checking the dates of ancient events studies?',['chronology','chivalrous conduct','the color of a chromatic scale'],'chronology','考订史事年代属于年代学。')]});
D('chrysalis',{etymology:e('chrysalis 经拉丁语来自希腊语 khrȳsallis“金色蛹”，关联 khrȳsos“金”；指蝴蝶或蛾在幼虫变成成虫期间的保护性蛹壳。','chrysalis'),contexts:[c('chrysalis.s1','昆虫观察','The butterfly remained inside its chrysalis through the cold weeks, then emerged with damp wings that needed time to dry.','蝴蝶在寒冷的数周里一直留在蛹中，随后破蛹而出，翅膀还湿着，需要时间晾干。','The butterfly remained inside its chrysalis through the cold weeks / then emerged with damp wings / that needed time to dry.','chrysalis 是 inside 的宾语；then 标记蛹期后羽化的下一阶段。','幼虫至成虫转变期间的保护性蛹壳是 chrysalis。')],mistakes:[m('The caterpillar emerged from its chrysalis before forming a pupa and completed metamorphosis as a larva.','The caterpillar formed a chrysalis, changed inside it, and later emerged as an adult butterfly.','蛹期发生在幼虫之后、成虫羽化之前，原句把生命周期顺序颠倒。')],quiz:[q('chrysalis',1,1,'A butterfly’s chrysalis is the protective case during?',['its change from larva to adult','its flight after adulthood only','its egg-laying season only'],'its change from larva to adult','chrysalis.s1 指蝴蝶或蛾蛹期的保护壳。'),q('chrysalis',2,1,'What emerges from a butterfly chrysalis?',['an adult butterfly','a chondrite','a young chihuahua'],'an adult butterfly','蛹期结束后蝴蝶羽化。'),q('chrysalis',3,1,'A chrysalis belongs to the life cycle of?',['a butterfly or moth','a cherry tree','a bank clerk'],'a butterfly or moth','蝴蝶和蛾会经过蛹期。'),q('chrysalis',4,1,'The Greek source of chrysalis is associated with?',['gold','water','sound'],'gold','词源与希腊语 khrȳsos“金”相关。')]});
D('chubby',{etymology:e('chubby 是 chub 加形容词后缀 -y 构成，可能与 round 或丰满的旧词义相关；其更早词源并不确定，现代形容稍胖、圆润的脸或身体。','chubby'),contexts:[c('chubby.s1','人物描写','The toddler’s chubby hands reached for the soft toy, and his round cheeks dimpled when his mother smiled.','小宝宝圆胖的小手伸向软玩具，妈妈一笑，他圆圆的脸颊便露出酒窝。','The toddler’s chubby hands reached for the soft toy / and his round cheeks dimpled / when his mother smiled.','chubby 修饰 hands；round cheeks 与后续表情补充圆润外貌。','手和脸颊略胖而圆润，体现 chubby.s1。')],mistakes:[m('The extremely thin child with sharp, hollow cheeks was described as chubby because no part of the body was rounded.','The round-cheeked child with plump hands was described as chubby.','极瘦、毫无圆润感与 chubby“圆胖的”不相符。')],quiz:[q('chubby',1,1,'A chubby baby has?',['a slightly plump, rounded body or face','a very tall, narrow body only','a shell made of chitin'],'a slightly plump, rounded body or face','chubby.s1 指稍胖、圆润。'),q('chubby',2,1,'Which description fits chubby cheeks?',['round and slightly plump','flat and completely hollow','covered in feathers'],'round and slightly plump','圆润略丰满的脸颊可称 chubby。'),q('chubby',3,1,'Chubby is usually used to describe?',['someone’s rounded appearance','the order of historical dates','an electrical charge'],'someone’s rounded appearance','该词通常描写脸或身体的圆胖外形。'),q('chubby',4,1,'A chubby hand is likely?',['small and plump','long and skeletal','made of stone'],'small and plump','小而圆胖的手符合该形容词。')]});
D('chug',{etymology:e('chug 可能是模仿蒸汽机或发动机短促重复声的拟声词；作名词指突突声，作动词可表示发着这种声响缓慢行进。','chug'),contexts:[c('chug.s2','铁路旅行','The old locomotive chugged up the hill, releasing a steady rhythm of exhaust as it pulled the passenger cars.','老式机车突突作响地爬上山坡，拉着客车车厢并有节奏地排出蒸汽。','The old locomotive chugged up the hill / releasing a steady rhythm of exhaust / as it pulled the passenger cars.','chugged up 表示发出突突声向上行进；as 从句说明机车牵引车厢。','机车边发声边缓慢移动，体现 chug.s2。')],mistakes:[m('The silent electric train chugged noiselessly across the station without producing any repeated engine sound.','The old train chugged noisily across the station, making a repeated engine sound.','chug 表示发出重复的短促引擎声；完全静音与该描写冲突。')],quiz:[q('chug',1,1,'A repeated short engine sound is a?',['chug','chide','chrysalis'],'chug','chug.s1 指发动机突突声。'),q('chug',2,2,'A train that chugs along?',['moves while making a repeated engine noise','stands silent with its engine off','turns into a plant pigment'],'moves while making a repeated engine noise','chug.s2 表示发着突突声前进。'),q('chug',3,1,'Which machine might chug?',['an old steam locomotive','a silent paper book','a checked shirt'],'an old steam locomotive','蒸汽机车可发出有节奏的突突声。'),q('chug',4,2,'“The boat chugged downriver” describes it?',['moving with a steady engine sound','being priced cheaply','undergoing a medical check-up'],'moving with a steady engine sound','船边发引擎声边行驶，符合动词义。')]});
D('chum',{etymology:e('chum 是英语口语词，早期与 chamber fellow“同住一室的伙伴”缩略形式相关；现作名词指密友，也可作动词表示结交、结伴交往。','chum'),contexts:[c('chum.s2','校园生活','The two students chummed together during their first term, studying in the library and sharing meals after class.','两名学生第一学期就结伴交往，下课后一起在图书馆学习、共进晚餐。','The two students chummed together during their first term / studying in the library / and sharing meals after class.','chum together 表示结伴交往；现在分词短语列出他们共同做的事。','形成友谊并结伴行动体现 chum.s2。')],mistakes:[m('The longtime chums had never met, spoken, or spent time together and had no friendship at all.','The longtime acquaintances had never met, spoken, or spent time together and had no friendship at all.','chum 指密友；从未认识或交往的人不能称为 chums。')],quiz:[q('chum',1,1,'A chum is an informal word for?',['a close friend','a chemical element','a dance sequence'],'a close friend','chum.s1 指口语里的好友。'),q('chum',2,2,'To chum together is to?',['form a friendship or spend time as companions','charge a hotel bill','turn a leaf yellow'],'form a friendship or spend time as companions','chum.s2 指结交或结伴交往。'),q('chum',3,1,'Which pair are chums?',['two close friends who spend time together','two strangers who have never met','a cashier and an unused checkmark'],'two close friends who spend time together','密友可称 chums。'),q('chum',4,2,'Students who chum together often?',['study or spend time as companions','avoid ever speaking to one another','measure the Sun’s chromosphere'],'study or spend time as companions','结伴共处、交往是 chum 的动词义。')]});
D('churn',{etymology:e('churn 作名词指搅奶油制黄油的器具，作动词意为剧烈搅拌；其词源不确定，也发展出胃或水面翻腾的比喻用法。','churn'),contexts:[c('churn.s2','海上天气','The storm made the bay churn with dark waves, tossing small boats against their moorings throughout the night.','风暴使海湾里的黑色波浪剧烈翻涌，整夜把小船摇得撞向系泊处。','The storm made the bay churn with dark waves / tossing small boats against their moorings / throughout the night.','make + 宾语 + churn 表示使海湾翻腾；with 引出翻涌物。','风暴造成水面剧烈翻滚，体现 churn.s2。')],mistakes:[m('The cream churned gently and stayed perfectly still without being stirred or separated into butter.','The cream was churned vigorously until it began to separate into butter.','搅乳制黄油需要搅动；原句说完全静止却称 churned，与动作矛盾。')],quiz:[q('churn',1,1,'To churn cream is to?',['stir it hard to make butter','freeze it into a solid block','paint it with charcoal'],'stir it hard to make butter','churn.s1 指搅拌奶油制黄油。'),q('churn',2,2,'Waves churn when they?',['move violently and turbulently','remain perfectly flat and still','turn into a checked pattern'],'move violently and turbulently','churn.s2 指波浪剧烈翻腾。'),q('churn',3,3,'A churn is?',['a container or machine for making butter','a hotel desk','a type of bird'],'a container or machine for making butter','churn.s3 指搅奶油制黄油的器具。'),q('churn',4,2,'If worry makes someone’s stomach churn, the stomach?',['feels unsettled or turns uneasily','becomes a bank account','is filled with butter'],'feels unsettled or turns uneasily','胃翻腾是剧烈不适的比喻用法。')]});
D('cicada',{etymology:e('cicada 源自拉丁语 cicada，指夏季鸣叫的蝉；英语从拉丁语借词，常用于昆虫本身，也可借指盛夏时持续的蝉鸣。','cicada'),contexts:[c('cicada.s2','夏日田园','The cicada’s loud chorus filled the orchard all afternoon, a familiar sound that made the still air feel unmistakably summery.','蝉鸣合唱整个下午回荡在果园里，这熟悉的声音让静止的空气带上了鲜明的盛夏气息。','The cicada’s loud chorus filled the orchard all afternoon / a familiar sound / that made the still air feel unmistakably summery.','cicada’s 表示蝉鸣所属；同位语解释其作为夏日意象的作用。','蝉鸣代表盛夏，体现 cicada.s2。')],mistakes:[m('The cicada sang through the winter because it was a silent mammal that never made a sound in summer.','The cicada sang loudly in summer, producing the high-pitched sound associated with the insect.','蝉是夏季鸣叫的昆虫，不是冬季无声的哺乳动物。')],quiz:[q('cicada',1,1,'A cicada is a large insect known for?',['a loud high-pitched summer sound','a hard metallic shell like a meteorite','making butter in a churn'],'a loud high-pitched summer sound','cicada.s1 指夏季鸣叫的大型昆虫。'),q('cicada',2,2,'“The cicada of summer” may refer to?',['the characteristic singing of cicadas','a tree’s red fruit','the Sun’s chromosphere'],'the characteristic singing of cicadas','cicada.s2 可转指蝉鸣这一夏季意象。'),q('cicada',3,1,'When are cicadas especially associated with being heard?',['in summer','during a silent winter night only','underwater in deep oceans'],'in summer','蝉鸣通常与夏季相关。'),q('cicada',4,1,'Which sound is most likely made by a cicada?',['a loud sustained insect buzz','a horse-drawn cart rolling','two coins chinking once'],'a loud sustained insect buzz','蝉会发出响亮而高的鸣声。')]});
D('cider',{etymology:e('cider 经古法语 cidre 来自拉丁语 sicera，后者借自希腊语 sikera“发酵饮料”；英式英语常指发酵苹果酒，美式英语也可指未发酵苹果汁。','cider'),contexts:[c('cider.s2','美式餐饮','At the farm stand, the label said “fresh cider,” and the unfermented apple juice was poured for children as well as adults.','农场摊位的标签写着“鲜苹果汁”，这种未发酵的果汁也供孩子和成年人饮用。','At the farm stand / the label said “fresh cider” / and the unfermented apple juice was poured / for children as well as adults.','cider 作 apple juice 的同位词；unfermented 明确为美式非酒精义。','未发酵苹果汁体现 cider.s2。')],mistakes:[m('The children drank alcoholic cider at the school lunch because the label said it was unfermented apple juice.','The children drank unfermented apple cider at the school lunch.','未发酵苹果汁不含发酵酒精；不能把它描述成 alcoholic cider。')],quiz:[q('cider',1,1,'In British use, cider is commonly?',['an alcoholic drink fermented from apple juice','an unfermented grape juice only','a type of hot pepper'],'an alcoholic drink fermented from apple juice','cider.s1 指发酵苹果酒。'),q('cider',2,2,'In much American use, fresh cider may be?',['unfermented apple juice','a fermented drink only','a kind of bank cheque'],'unfermented apple juice','cider.s2 在美式用法中可指未发酵苹果汁。'),q('cider',3,1,'Hard cider generally means?',['alcoholic fermented apple drink','plain water with chlorine','a dance arrangement'],'alcoholic fermented apple drink','hard cider 特指含酒精的发酵苹果酒。'),q('cider',4,2,'A child at a US farm stand may drink cider that is?',['fresh and unfermented','necessarily alcoholic','made from chitin'],'fresh and unfermented','美式 cider 可指新鲜未发酵苹果汁。')]});
D('cigarette',{etymology:e('cigarette 经法语 cigarette 来自 cigare“雪茄”加指小后缀 -ette；指将细切烟草卷在纸里的小型烟卷，现代香烟常装过滤嘴。','cigarette'),contexts:[c('cigarette.s1','公共健康','The cigarette smoke drifted toward the playground, so the sign asked visitors to smoke only in the covered area away from children.','香烟烟雾飘向游乐场，因此标牌请访客只在远离儿童的有顶区域吸烟。','The cigarette smoke drifted toward the playground / so the sign asked visitors to smoke only in the covered area / away from children.','cigarette 是 smoke 的定语中心词；so 引出设置吸烟区域的原因。','纸卷烟草燃烧产生烟雾，语境明确指香烟。')],mistakes:[m('A cigarette is a roll of tobacco wrapped in paper, but the sentence said it was made only of fresh fruit and contained no tobacco.','A cigarette is finely cut tobacco rolled in paper, often with a filter.','cigarette 的定义包含纸卷烟草；纯水果不符合。')],quiz:[q('cigarette',1,1,'A cigarette is usually made of?',['finely cut tobacco rolled in paper','a bundle of fresh cherries','a small metal battery'],'finely cut tobacco rolled in paper','cigarette.s1 指纸卷细切烟草的香烟。'),q('cigarette',2,1,'Many modern cigarettes include a?',['filter','chondrule','chateau key'],'filter','现代香烟很多带有过滤嘴。'),q('cigarette',3,1,'Which item is a cigarette?',['a paper-wrapped roll of tobacco','a pair of chopsticks','a small checked cloth'],'a paper-wrapped roll of tobacco','纸卷烟丝是香烟。'),q('cigarette',4,1,'The suffix -ette in cigarette originally suggests?',['a smaller form','a plural verb','a medical condition'],'a smaller form','法语 -ette 是指小后缀。')]});
D('cinderella',{etymology:e('Cinderella 取自童话人物 Cinderella，来自法语 Cendrillon“灰烬姑娘”（cendre“灰烬”加指小形式）；小写转为普通名词，可指长期受忽视后获得成功的人或事物。','cinderella'),contexts:[c('cinderella.s2','体育报道','For years the women’s rowing team received little funding, but its national title turned the program into the season’s cinderella story.','多年来，女子赛艇队几乎得不到经费，但全国冠军让这支队伍成为本赛季从默默无闻到成功的故事。','For years the women’s rowing team received little funding / but its national title turned the program / into the season’s cinderella story.','cinderella 作名词修饰 story；but 对照长期冷落与突然夺冠。','长期被忽视后取得成功，符合比喻义 s2。')],mistakes:[m('The well-funded defending champion was called a cinderella because it had dominated the league for twenty years and was never overlooked.','The little-known team that rose from obscurity to win the title was called a cinderella.','长期称霸且从未受冷落的队伍不符合“被低估后成功”的 cinderella 比喻义。')],quiz:[q('cinderella',1,1,'In the fairy tale, Cinderella is?',['a heroine mistreated before her fortunes change','a meteorite mineral','a famous choreographer'],'a heroine mistreated before her fortunes change','cinderella.s1 指童话中的灰姑娘。'),q('cinderella',2,2,'A “Cinderella team” is often?',['undervalued for a long time before succeeding','the longtime dominant favorite','a team that never competes'],'undervalued for a long time before succeeding','cinderella.s2 指长期受冷落后成功的人或事物。'),q('cinderella',3,1,'The name Cinderella is linked to the idea of?',['ashes','chlorine gas','a checked pattern'],'ashes','法语名字 Cendrillon 与灰烬有关。'),q('cinderella',4,2,'A small club winning a major title after years of neglect may be called?',['a cinderella story','a check-up','a chondrule'],'a cinderella story','从被低估到成功契合比喻义。')]});
D('cinematic',{etymology:e('cinematic 由 cinema 加形容词后缀 -atic 构成；cinema 经法语来自希腊语 kinēma“运动”，源于 kinein“移动”，既指电影艺术，也形容具有电影般感染力的效果。','cinematic'),contexts:[c('cinematic.s2','影像叙事','The director used a slow aerial shot over the empty coast, giving the documentary a cinematic opening despite its modest budget.','导演用缓慢的海岸空镜开场，尽管预算有限，纪录片仍呈现出电影般的质感。','The director used a slow aerial shot over the empty coast / giving the documentary a cinematic opening / despite its modest budget.','cinematic 修饰 opening；分词短语说明镜头营造的效果。','空镜营造电影般的视觉感染力，体现 cinematic.s2。')],mistakes:[m('The cinematic scene felt like a plain unedited spreadsheet with no visual storytelling or film-like qualities.','The cinematic scene used carefully framed images and movement to create a film-like effect.','缺乏任何视觉叙事或电影感，不能称为 cinematic.s2。')],quiz:[q('cinematic',1,1,'A cinematic technique is related to?',['films or filmmaking','plant disease','tribal leadership'],'films or filmmaking','cinematic.s1 指与电影或电影制作有关。'),q('cinematic',2,2,'A cinematic landscape has?',['a dramatic, film-like quality','only the appearance of a bank cheque','no visual effect at all'],'a dramatic, film-like quality','cinematic.s2 指有电影感、富有感染力。'),q('cinematic',3,1,'A cinematic camera shot belongs to?',['film production','a medical check-up','a chivalry code'],'film production','电影摄影镜头属于电影制作。'),q('cinematic',4,2,'Which description best fits cinematic imagery?',['visually striking like a scene in a film','a random list of dates','a dark room with no image'],'visually striking like a scene in a film','电影般的视觉效果体现比喻义。')]});
D('cinematograph',{etymology:e('cinematograph 由希腊语 kinēma“运动”与 -graph“记录、描绘”构成，经法语 Cinématographe 进入英语，早期指拍摄或放映活动影像的机器，也可作动词表示拍摄。','cinematograph'),contexts:[c('cinematograph.s2','早期新闻片','The crew cinematographed the harbor opening, recording the arriving ships so audiences across the country could see the event later.','摄制组把港口开放仪式拍成活动影像，记录抵达的船只，让全国观众之后也能看到这一事件。','The crew cinematographed the harbor opening / recording the arriving ships / so audiences across the country could see the event later.','cinematographed 是及物动词过去式；recording 说明拍摄内容。','把仪式记录成活动影像体现 cinematograph.s2。')],mistakes:[m('The museum displayed a cinematograph, described as a modern smartphone app that cannot record or project moving pictures.','The museum displayed an early cinematograph, a machine designed to record or project moving pictures.','cinematograph 指早期活动影像摄影或放映机器，不是不能拍放影像的现代软件。')],quiz:[q('cinematograph',1,1,'An early cinematograph was a machine for?',['taking or showing motion pictures','making butter from cream','measuring a plant’s chlorophyll'],'taking or showing motion pictures','cinematograph.s1 指早期电影摄影或放映机。'),q('cinematograph',2,2,'To cinematograph an event is to?',['record it as moving pictures','arrange its dates chronologically','charge guests at checkout'],'record it as moving pictures','cinematograph.s2 作动词指拍摄活动影像。'),q('cinematograph',3,1,'A cinematograph belongs to the history of?',['early cinema','agricultural chemistry','medieval chivalry'],'early cinema','cinematograph 是电影史早期设备。'),q('cinematograph',4,2,'A crew cinematographed a parade, meaning it?',['filmed the parade','sold the parade tickets','chided the parade organizers'],'filmed the parade','把游行拍成活动影像就是 cinematograph 的动词义。')]});

})();
